/// 包貨日期。；啟用最低需求版本：LITE-CORE\n  plDate              DateTime      @map(\"pl_date\") @db.Date\n  /// 來源撿貨單ID（FK nx03_pk）。；啟用最低需求版本：LITE-CORE\n  pkId                String        @map(\"pk_id\") @db.VarChar(15)\n  /// 包貨類型（D=配送/P=自取/C=寄貨/T=調撥）。所有出貨類型均需經過包貨環節。；啟用最低需求版本：LITE-CORE\n  plType              String        @map(\"pl_type\") @db.VarChar(1)\n  /// 狀態（P=待包貨/C=包貨中/F=已完成/S=已寄出/V=作廢）。；啟用最低需求版本：LITE-CORE\n  status              String        @default(\"P\") @db.VarChar(1)\n  /// 第三方物流業者名稱（pl_type=C時填入）。；啟用最低需求版本：LITE-CORE\n  logisticsProvider   String?       @map(\"logistics_provider\") @db.VarChar(50)\n  /// 第三方物流單號（寄出後倉管組長填入）。；啟用最低需求版本：LITE-CORE\n  logisticsTrackingNo String?       @map(\"logistics_tracking_no\") @db.VarChar(50)\n  /// 寄出時間（倉管組長確認交付物流後填入）。；啟用最低需求版本：LITE-CORE\n  shippedAt           DateTime?     @map(\"shipped_at\")\n  /// 寄出確認人（倉管組長，使用者ID）。；啟用最低需求版本：LITE-CORE\n  shippedBy           String?       @map(\"shipped_by\") @db.VarChar(15)\n  /// 包貨開始時間（計時器啟動）。；啟用最低需求版本：LITE-CORE\n  startedAt           DateTime?     @map(\"started_at\")\n  /// 包貨完成時間（計時器結束）。；啟用最低需求版本：LITE-CORE\n  completedAt         DateTime?     @map(\"completed_at\")\n  /// 包貨完成人（倉管專員，使用者ID）。；啟用最低需求版本：LITE-CORE\n  completedBy         String?       @map(\"completed_by\") @db.VarChar(15)\n  /// 備註。；啟用最低需求版本：LITE-CORE\n  remark              String?       @db.VarChar(200)\n  /// 建立時間。；啟用最低需求版本：LITE-CORE\n  createdAt           DateTime      @default(now()) @map(\"created_at\")\n  /// 建立人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：LITE-CORE\n  createdBy           String        @map(\"created_by\") @db.VarChar(15)\n  /// 更新時間。；啟用最低需求版本：LITE-CORE\n  updatedAt           DateTime      @updatedAt @map(\"updated_at\")\n  /// 更新人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：LITE-CORE\n  updatedBy           String        @map(\"updated_by\") @db.VarChar(15)\n  tenant              Nx99Tenant    @relation(\"R_Nx03Pl_tenantId\", fields: [tenantId], references: [id])\n  warehouse           Nx01Warehouse @relation(\"R_Nx03Pl_warehouseId\", fields: [warehouseId], references: [id])\n  pk                  Nx03Pk        @relation(\"R_Nx03Pl_pkId\", fields: [pkId], references: [id])\n  rev_Nx03Parcel_plId Nx03Parcel[]  @relation(\"R_Nx03Parcel_plId\")\n  rev_Nx03PlItem_plId Nx03PlItem[]  @relation(\"R_Nx03PlItem_plId\")\n\n  @@unique([docNo])\n  @@map(\"nx03_pl\")\n}\n\n/// =======================================================\n/// Nx03PlItem — DB table `nx03_pl_item`\n/// =======================================================\nmodel Nx03PlItem {\n  /// [NX03]+[PLIT]+[7碼流水號]，EX : NX03PLIT0000001；啟用最低需求版本：LITE-CORE\n  id        String      @id @default(dbgenerated(\"gen_nx03_pl_item_id()\")) @db.VarChar(15)\n  /// 對應包貨單表頭ID（FK nx03_pl）。；啟用最低需求版本：LITE-CORE\n  plId      String      @map(\"pl_id\") @db.VarChar(15)\n  /// 對應包裹ID（FK nx03_parcel）。；啟用最低需求版本：LITE-CORE\n  parcelId  String?     @map(\"parcel_id\") @db.VarChar(15)\n  /// 對應撿貨明細ID（FK nx03_pk_item）。；啟用最低需求版本：LITE-CORE\n  pkItemId  String      @map(\"pk_item_id\") @db.VarChar(15)\n  /// 明細行號（1,2,3…）。；啟用最低需求版本：LITE-CORE\n  lineNo    Int         @map(\"line_no\")\n  /// 零件ID（FK nx01_part）。；啟用最低需求版本：LITE-CORE\n  partId    String      @map(\"part_id\") @db.VarChar(15)\n  /// 零件料號快照。；啟用最低需求版本：LITE-CORE\n  partNo    String      @map(\"part_no\") @db.VarChar(50)\n  /// 零件名稱快照。；啟用最低需求版本：LITE-CORE\n  partName  String      @map(\"part_name\") @db.VarChar(200)\n  /// 包裝數量。；啟用最低需求版本：LITE-CORE\n  qty       Decimal     @db.Decimal(14, 4)\n  /// 備註。；啟用最低需求版本：LITE-CORE\n  remark    String?     @db.VarChar(200)\n  /// 建立時間。；啟用最低需求版本：LITE-CORE\n  createdAt DateTime    @default(now()) @map(\"created_at\")\n  /// 更新時間。；啟用最低需求版本：LITE-CORE\n  updatedAt DateTime    @updatedAt @map(\"updated_at\")\n  /// 更新人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：LITE-CORE\n  updatedBy String      @map(\"updated_by\") @db.VarChar(15)\n  pl        Nx03Pl      @relation(\"R_Nx03PlItem_plId\", fields: [plId], references: [id])\n  parcel    Nx03Parcel? @relation(\"R_Nx03PlItem_parcelId\", fields: [parcelId], references: [id])\n  pkItem    Nx03PkItem  @relation(\"R_Nx03PlItem_pkItemId\", fields: [pkItemId], references: [id])\n  part      Nx01Part    @relation(\"R_Nx03PlItem_partId\", fields: [partId], references: [id])\n\n  @@map(\"nx03_pl_item\")\n}\n\n/// =======================================================\n/// Nx03Shortage — DB table `nx03_shortage`\n/// =======================================================\nmodel Nx03Shortage {\n  /// [NX03]+[SHOR]+[7碼流水號]，EX : NX03SHOR0000001；啟用最低需求版本：PLUS\n  id              String        @id @default(dbgenerated(\"gen_nx03_shortage_id()\")) @db.VarChar(15)\n  /// 租戶 ID（外鍵）(@@unique([tenantId, partId, warehouseId]))；啟用最低需求版本：PLUS\n  tenantId        String        @map(\"tenant_id\") @db.VarChar(15)\n  /// 零件 ID (@@unique([tenantId, partId, warehouseId]))；啟用最低需求版本：PLUS\n  partId          String        @map(\"part_id\") @db.VarChar(15)\n  /// 缺貨倉庫 ID (@@unique([tenantId, partId, warehouseId]))；啟用最低需求版本：PLUS\n  warehouseId     String        @map(\"warehouse_id\") @db.VarChar(15)\n  /// 發現時的現存量快照；啟用最低需求版本：PLUS\n  onHandQty       Decimal       @map(\"on_hand_qty\") @db.Decimal(14, 4)\n  /// 安全量快照；啟用最低需求版本：PLUS\n  minQty          Decimal       @map(\"min_qty\") @db.Decimal(14, 4)\n  /// 缺貨量（min_qty - on_hand_qty）；啟用最低需求版本：PLUS\n  shortageQty     Decimal       @map(\"shortage_qty\") @db.Decimal(14, 4)\n  /// 建議訂購量（max_qty - on_hand_qty）；啟用最低需求版本：PLUS\n  suggestOrderQty Decimal       @map(\"suggest_order_qty\") @db.Decimal(14, 4)\n  /// 狀態。( O=OPEN / R=RFQ已建立 / C=CLOSED / I=IGNORED )；啟用最低需求版本：PLUS\n  status          String        @default(\"O\") @db.VarChar(1)\n  /// 關聯 RFQ（轉 RFQ 後填入）；啟用最低需求版本：PLUS\n  refRfqId        String?       @map(\"ref_rfq_id\") @db.VarChar(15)\n  /// 偵測時間（系統自動產生）；啟用最低需求版本：PLUS\n  detectedAt      DateTime      @default(now()) @map(\"detected_at\")\n  /// 解決時間（CLOSED 時填入）；啟用最低需求版本：PLUS\n  resolvedAt      DateTime?     @map(\"resolved_at\")\n  /// 備註；啟用最低需求版本：PLUS\n  remark          String?       @db.VarChar(200)\n  /// 建立時間。；啟用最低需求版本：PLUS\n  createdAt       DateTime      @default(now()) @map(\"created_at\")\n  /// 建立人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：PLUS\n  createdBy       String        @map(\"created_by\") @db.VarChar(15)\n  /// 更新時間。；啟用最低需求版本：PLUS\n  updatedAt       DateTime      @updatedAt @map(\"updated_at\")\n  /// 更新人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：PLUS\n  updatedBy       String        @map(\"updated_by\") @db.VarChar(15)\n  tenant          Nx99Tenant    @relation(\"R_Nx03Shortage_tenantId\", fields: [tenantId], references: [id])\n  part            Nx01Part      @relation(\"R_Nx03Shortage_partId\", fields: [partId], references: [id])\n  warehouse       Nx01Warehouse @relation(\"R_Nx03Shortage_warehouseId\", fields: [warehouseId], references: [id])\n  refRfq          Nx02Rfq?      @relation(\"R_Nx03Shortage_refRfqId\", fields: [refRfqId], references: [id])\n\n  @@map(\"nx03_shortage\")\n}\n\n/// =======================================================\n/// Nx03St — DB table `nx03_st`\n/// =======================================================\nmodel Nx03St {\n  /// [NX03]+[STHD]+[7碼流水號]，EX : NX03STHD0000001；啟用最低需求版本：PLUS\n  id                     String        @id @default(dbgenerated(\"gen_nx03_st_id()\")) @db.VarChar(15)\n  /// 租戶 ID（外鍵）；啟用最低需求版本：PLUS\n  tenantId               String        @map(\"tenant_id\") @db.VarChar(15)\n  /// 調撥單號（唯一），[ST]+[年月]+[倉別]+[5碼流水號]，EX：ST-202602-Z01-00001；啟用最低需求版本：PLUS\n  docNo                  String        @map(\"doc_no\") @db.VarChar(30)\n  /// 調撥日期；啟用最低需求版本：PLUS\n  stDate                 DateTime      @map(\"st_date\") @db.Date\n  /// 來源倉庫 (外鍵)；啟用最低需求版本：PLUS\n  fromWarehouseId        String        @map(\"from_warehouse_id\") @db.VarChar(15)\n  /// 目標倉庫 (外鍵)；啟用最低需求版本：PLUS\n  toWarehouseId          String        @map(\"to_warehouse_id\") @db.VarChar(15)\n  /// DRAFT / TRANSIT / RECEIVED / CANCELLED；啟用最低需求版本：PLUS\n  status                 String        @default(\"DRAFT\") @db.VarChar(30)\n  /// 備註；啟用最低需求版本：PLUS\n  remark                 String?       @db.VarChar(200)\n  /// 建立時間。；啟用最低需求版本：PLUS\n  createdAt              DateTime      @default(now()) @map(\"created_at\")\n  /// 建立人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：PLUS\n  createdBy              String        @map(\"created_by\") @db.VarChar(15)\n  /// 更新時間。；啟用最低需求版本：PLUS\n  updatedAt              DateTime      @updatedAt @map(\"updated_at\")\n  /// 更新人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：PLUS\n  updatedBy              String        @map(\"updated_by\") @db.VarChar(15)\n  /// 過帳時間（POSTED 才有）；啟用最低需求版本：PLUS\n  postedAt               DateTime?     @map(\"posted_at\")\n  /// 過帳人（POSTED 才有）；啟用最低需求版本：PLUS\n  postedBy               String?       @map(\"posted_by\") @db.VarChar(15)\n  /// 作廢時間；啟用最低需求版本：PLUS\n  voidedAt               DateTime?     @map(\"voided_at\")\n  /// 作廢人（使用者 ID）；啟用最低需求版本：PLUS\n  voidedBy               String?       @map(\"voided_by\") @db.VarChar(15)\n  /// 調撥類型（A=自動配貨系統產生/M=手動申請）。；啟用最低需求版本：LITE-CORE\n  stType                 String        @default(\"M\") @map(\"st_type\") @db.VarChar(1)\n  /// 觸發來源（R=進貨後自動配貨/S=SO銷貨需求缺貨/M=手動）。；啟用最低需求版本：LITE-CORE\n  triggerSource          String?       @map(\"trigger_source\") @db.VarChar(1)\n  /// 關聯銷貨單ID（trigger_source=S時填入）。；啟用最低需求版本：LITE-CORE\n  refSoId                String?       @map(\"ref_so_id\") @db.VarChar(15)\n  /// 關聯進貨單ID（trigger_source=R時填入）。；啟用最低需求版本：LITE-CORE\n  refRrId                String?       @map(\"ref_rr_id\") @db.VarChar(15)\n  /// 他倉倉管組長審核核准時間。；啟用最低需求版本：LITE-CORE\n  approvedAt             DateTime?     @map(\"approved_at\")\n  /// 核准人（他倉倉管組長，使用者ID）。；啟用最低需求版本：LITE-CORE\n  approvedBy             String?       @map(\"approved_by\") @db.VarChar(15)\n  /// 目標倉確認收貨時間（計時器結束時間）。；啟用最低需求版本：LITE-CORE\n  receivedAt             DateTime?     @map(\"received_at\")\n  /// 收貨確認人（目標倉倉管專員，使用者ID）。；啟用最低需求版本：LITE-CORE\n  receivedBy             String?       @map(\"received_by\") @db.VarChar(15)\n  tenant                 Nx99Tenant    @relation(\"R_Nx03St_tenantId\", fields: [tenantId], references: [id])\n  fromWarehouse          Nx01Warehouse @relation(\"R_Nx03St_fromWarehouseId\", fields: [fromWarehouseId], references: [id])\n  toWarehouse            Nx01Warehouse @relation(\"R_Nx03St_toWarehouseId\", fields: [toWarehouseId], references: [id])\n  refSo                  Nx04So?       @relation(\"R_Nx03St_refSoId\", fields: [refSoId], references: [id])\n  refRr                  Nx02Rr?       @relation(\"R_Nx03St_refRrId\", fields: [refRrId], references: [id])\n  rev_Nx03PkItem_refStId Nx03PkItem[]  @relation(\"R_Nx03PkItem_refStId\")\n  rev_Nx03StItem_stId    Nx03StItem[]  @relation(\"R_Nx03StItem_stId\")\n  rev_Nx04SoItem_stId    Nx04SoItem[]  @relation(\"R_Nx04SoItem_stId\")\n\n  @@map(\"nx03_st\")\n}\n\n/// =======================================================\n/// Nx03StItem — DB table `nx03_st_item`\n/// =======================================================\nmodel Nx03StItem {\n  /// [NX03]+[STIT]+[7碼流水號]，EX : NX03STIT0000001；啟用最低需求版本：PLUS\n  id             String         @id @default(dbgenerated(\"gen_nx03_st_item_id()\")) @db.VarChar(15)\n  /// 對應調撥單表頭 ID；啟用最低需求版本：PLUS\n  stId           String         @map(\"st_id\") @db.VarChar(15)\n  /// 明細行號（1,2,3…）；啟用最低需求版本：PLUS\n  lineNo         Int            @default(1) @map(\"line_no\")\n  /// 零件 ID；啟用最低需求版本：PLUS\n  partId         String         @map(\"part_id\") @db.VarChar(15)\n  /// 料號快照（歷史查價/避免主檔改動）；啟用最低需求版本：PLUS\n  partNo         String         @map(\"part_no\") @db.VarChar(50)\n  /// 品名快照；啟用最低需求版本：PLUS\n  partName       String         @map(\"part_name\") @db.VarChar(200)\n  /// 品牌（可空）；啟用最低需求版本：PLUS\n  partBrandId    String?        @map(\"part_brand_id\") @db.VarChar(15)\n  /// 出貨庫位；啟用最低需求版本：PLUS\n  fromLocationId String?        @map(\"from_location_id\") @db.VarChar(15)\n  /// 目標庫位；啟用最低需求版本：PLUS\n  toLocationId   String?        @map(\"to_location_id\") @db.VarChar(15)\n  /// 銷貨數量；啟用最低需求版本：PLUS\n  qty            Decimal        @default(0) @db.Decimal(14, 4)\n  /// 出庫成本（過帳時寫入；預設抓 stock_balance.avg_cost）；啟用最低需求版本：PLUS\n  unitCost       Decimal        @default(0) @map(\"unit_cost\") @db.Decimal(14, 4)\n  /// 備註；啟用最低需求版本：PLUS\n  remark         String?        @db.VarChar(200)\n  /// 建立時間。；啟用最低需求版本：PLUS\n  createdAt      DateTime       @default(now()) @map(\"created_at\")\n  /// 建立人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：PLUS\n  createdBy      String         @map(\"created_by\") @db.VarChar(15)\n  /// 更新時間。；啟用最低需求版本：PLUS\n  updatedAt      DateTime       @updatedAt @map(\"updated_at\")\n  /// 更新人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：PLUS\n  updatedBy      String         @map(\"updated_by\") @db.VarChar(15)\n  /// 實際收到數量（目標倉確認收貨後填入）。若與qty不符需通知倉管組長處理。；啟用最低需求版本：LITE-CORE\n  receivedQty    Decimal?       @map(\"received_qty\") @db.Decimal(14, 4)\n  /// 來源銷貨明細 ID（可空：手動調撥無對應 SO；SO 觸發必填）。反向追蹤這個 ST 明細是為了哪張 SO 的哪個 line 而存在。Phase 0 D3 新增、2026-04-25 改 nullable（trans-table CHECK 不可行，application-layer 自律）。；啟用最低需求版本：PLUS\n  sourceSoItemId String?        @map(\"source_so_item_id\") @db.VarChar(15)\n  st             Nx03St         @relation(\"R_Nx03StItem_stId\", fields: [stId], references: [id])\n  part           Nx01Part       @relation(\"R_Nx03StItem_partId\", fields: [partId], references: [id])\n  partBrand      Nx01PartBrand? @relation(\"R_Nx03StItem_partBrandId\", fields: [partBrandId], references: [id])\n  fromLocation   Nx01Location?  @relation(\"R_Nx03StItem_fromLocationId\", fields: [fromLocationId], references: [id])\n  toLocation     Nx01Location?  @relation(\"R_Nx03StItem_toLocationId\", fields: [toLocationId], references: [id])\n  sourceSoItem   Nx04SoItem?    @relation(\"R_Nx03StItem_sourceSoItemId\", fields: [sourceSoItemId], references: [id])\n\n  @@index([sourceSoItemId], map: \"nx03_st_item_source_so_item_idx\")\n  @@map(\"nx03_st_item\")\n}\n\n/// =======================================================\n/// Nx03StockBalance — DB table `nx03_stock_balance`\n/// =======================================================\nmodel Nx03StockBalance {\n  /// [NX03]+[STBL]+[7碼流水號]，EX : NX03STBL0000001；啟用最低需求版本：LITE\n  id           String        @id @default(dbgenerated(\"gen_nx03_stock_balance_id()\")) @db.VarChar(15)\n  /// 租戶 ID（外鍵）(@@unique([tenantId, partId, warehouseId]))；啟用最低需求版本：LITE\n  tenantId     String        @map(\"tenant_id\") @db.VarChar(15)\n  /// 零件 ID (@@unique([tenantId, partId, warehouseId]))；啟用最低需求版本：LITE\n  partId       String        @map(\"part_id\") @db.VarChar(15)\n  /// 倉庫 ID (@@unique([tenantId, partId, warehouseId]))；啟用最低需求版本：LITE\n  warehouseId  String        @map(\"warehouse_id\") @db.VarChar(15)\n  /// 現存量（實際在架數量，可為負值）；啟用最低需求版本：LITE\n  onHandQty    Decimal       @default(0) @map(\"on_hand_qty\") @db.Decimal(14, 4)\n  /// 已佔用量（已開銷貨單但未出庫，LITE）；啟用最低需求版本：LITE\n  reservedQty  Decimal       @default(0) @map(\"reserved_qty\") @db.Decimal(14, 4)\n  /// 可用量 = on_hand_qty - reserved_qty（存 DB，同步更新）；啟用最低需求版本：LITE\n  availableQty Decimal       @default(0) @map(\"available_qty\") @db.Decimal(14, 4)\n  /// 調撥中數量（已出來源倉但未到目標倉，PLUS）；啟用最低需求版本：PLUS\n  inTransitQty Decimal       @default(0) @map(\"in_transit_qty\") @db.Decimal(14, 4)\n  /// 移動平均成本；啟用最低需求版本：LITE\n  avgCost      Decimal       @default(0) @map(\"avg_cost\") @db.Decimal(14, 4)\n  /// 庫存總值（on_hand_qty * avg_cost）；啟用最低需求版本：LITE\n  stockValue   Decimal       @default(0) @map(\"stock_value\") @db.Decimal(14, 2)\n  /// 最近一次入庫時間（PO/調整入）；啟用最低需求版本：LITE\n  lastInAt     DateTime?     @map(\"last_in_at\")\n  /// 最近一次出庫時間（SO/調整出）；啟用最低需求版本：LITE\n  lastOutAt    DateTime?     @map(\"last_out_at\")\n  /// 最近一次異動時間（任一 IN/OUT/ADJUST）；啟用最低需求版本：LITE\n  lastMoveAt   DateTime      @default(now()) @map(\"last_move_at\")\n  /// 是否啟用（通常 TRUE；若某庫位停用可控制）；啟用最低需求版本：LITE\n  isActive     Boolean       @default(true) @map(\"is_active\")\n  /// 建立時間。；啟用最低需求版本：LITE\n  createdAt    DateTime      @default(now()) @map(\"created_at\")\n  /// 建立人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：LITE\n  createdBy    String        @map(\"created_by\") @db.VarChar(15)\n  /// 更新時間。；啟用最低需求版本：LITE\n  updatedAt    DateTime      @updatedAt @map(\"updated_at\")\n  /// 更新人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：LITE\n  updatedBy    String        @map(\"updated_by\") @db.VarChar(15)\n  tenant       Nx99Tenant    @relation(\"R_Nx03StockBalance_tenantId\", fields: [tenantId], references: [id])\n  part         Nx01Part      @relation(\"R_Nx03StockBalance_partId\", fields: [partId], references: [id])\n  warehouse    Nx01Warehouse @relation(\"R_Nx03StockBalance_warehouseId\", fields: [warehouseId], references: [id])\n\n  @@unique([tenantId, partId, warehouseId])\n  @@map(\"nx03_stock_balance\")\n}\n\n/// =======================================================\n/// Nx03StockLedger — DB table `nx03_stock_ledger`\n/// =======================================================\nmodel Nx03StockLedger {\n  /// [NX03]+[STLE]+[7碼流水號]，EX : NX03STLE0000001；啟用最低需求版本：LITE\n  id            String        @id @default(dbgenerated(\"gen_nx03_stock_ledger_id()\")) @db.VarChar(15)\n  /// 租戶 ID（外鍵）；啟用最低需求版本：LITE\n  tenantId      String        @map(\"tenant_id\") @db.VarChar(15)\n  /// 異動時間；啟用最低需求版本：LITE\n  movementDate  DateTime      @default(now()) @map(\"movement_date\")\n  /// 零件 ID；啟用最低需求版本：LITE\n  partId        String        @map(\"part_id\") @db.VarChar(15)\n  /// 倉庫 ID；啟用最低需求版本：LITE\n  warehouseId   String        @map(\"warehouse_id\") @db.VarChar(15)\n  /// 庫位 ID；啟用最低需求版本：LITE\n  locationId    String        @map(\"location_id\") @db.VarChar(15)\n  /// 異動類型。( I=IN, O=OUT, A=ADJUST )；啟用最低需求版本：LITE\n  movementType  String        @map(\"movement_type\") @db.VarChar(1)\n  /// 入庫數量；啟用最低需求版本：LITE\n  qtyIn         Decimal       @default(0) @map(\"qty_in\") @db.Decimal(14, 4)\n  /// 出庫數量；啟用最低需求版本：LITE\n  qtyOut        Decimal       @default(0) @map(\"qty_out\") @db.Decimal(14, 4)\n  /// 異動單位成本；啟用最低需求版本：LITE\n  unitCost      Decimal       @default(0) @map(\"unit_cost\") @db.Decimal(14, 4)\n  /// 異動總成本（qty差 * unit_cost）；啟用最低需求版本：LITE\n  totalCost     Decimal       @default(0) @map(\"total_cost\") @db.Decimal(14, 2)\n  /// 異動後庫存數量（可選擇存或即時計算）；啟用最低需求版本：LITE\n  balanceQty    Decimal       @default(0) @map(\"balance_qty\") @db.Decimal(14, 4)\n  /// 異動後平均成本（移動平均）；啟用最低需求版本：LITE\n  balanceCost   Decimal       @default(0) @map(\"balance_cost\") @db.Decimal(14, 4)\n  /// 來源模組：NX02（採購）/ NX03（庫存）/ NX04（銷售）；啟用最低需求版本：LITE\n  sourceModule  String        @map(\"source_module\") @db.VarChar(10)\n  /// 來源單據類型（P=進貨RR / S=銷貨SO / T=盤點 / I=開帳存 / X=調撥 / R=退貨）；啟用最低需求版本：LITE\n  sourceDocType String        @map(\"source_doc_type\") @db.VarChar(1)\n  /// 來源單據 ID；啟用最低需求版本：LITE\n  sourceDocId   String        @map(\"source_doc_id\") @db.VarChar(15)\n  /// 來源明細 ID；啟用最低需求版本：LITE\n  sourceItemId  String?       @map(\"source_item_id\") @db.VarChar(15)\n  /// 建立時間；啟用最低需求版本：LITE\n  createdAt     DateTime      @default(now()) @map(\"created_at\")\n  tenant        Nx99Tenant    @relation(\"R_Nx03StockLedger_tenantId\", fields: [tenantId], references: [id])\n  part          Nx01Part      @relation(\"R_Nx03StockLedger_partId\", fields: [partId], references: [id])\n  warehouse     Nx01Warehouse @relation(\"R_Nx03StockLedger_warehouseId\", fields: [warehouseId], references: [id])\n  location      Nx01Location  @relation(\"R_Nx03StockLedger_locationId\", fields: [locationId], references: [id])\n\n  @@map(\"nx03_stock_ledger\")\n}\n\n/// =======================================================\n/// Nx03StockTake — DB table `nx03_stock_take`\n/// =======================================================\nmodel Nx03StockTake {\n  /// [NX03]+[STTK]+[7碼流水號]，EX : NX03STTK0000001；啟用最低需求版本：LITE\n  id                                String              @id @default(dbgenerated(\"gen_nx03_stock_take_id()\")) @db.VarChar(15)\n  /// 租戶 ID（外鍵）；啟用最低需求版本：LITE\n  tenantId                          String              @map(\"tenant_id\") @db.VarChar(15)\n  /// 盤點單號（唯一），[SL]+[年月]+[倉別]+[5碼流水號]，EX：SL-202602-Z01-00001；啟用最低需求版本：LITE\n  docNo                             String              @map(\"doc_no\") @db.VarChar(30)\n  /// 盤點日期；啟用最低需求版本：LITE\n  stockTakeDate                     DateTime            @map(\"stock_take_date\") @db.Date\n  /// 盤點倉庫（LITE 先以單倉/單次盤點為主）；啟用最低需求版本：LITE\n  warehouseId                       String              @map(\"warehouse_id\") @db.VarChar(15)\n  /// 盤點範圍。( F=FULL（全倉）, P=PARTIAL（指定料號/庫位）)；啟用最低需求版本：LITE\n  scopeType                         String              @default(\"F\") @map(\"scope_type\") @db.VarChar(1)\n  /// 狀態（DRAFT / COUNTING / ADJUSTING / POSTED / CANCELLED）；啟用最低需求版本：LITE\n  status                            String              @default(\"DRAFT\") @db.VarChar(30)\n  /// 備註；啟用最低需求版本：LITE\n  remark                            String?             @db.VarChar(200)\n  /// 建立時間。；啟用最低需求版本：LITE\n  createdAt                         DateTime            @default(now()) @map(\"created_at\")\n  /// 建立人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：LITE\n  createdBy                         String              @map(\"created_by\") @db.VarChar(15)\n  /// 更新時間。；啟用最低需求版本：LITE\n  updatedAt                         DateTime            @updatedAt @map(\"updated_at\")\n  /// 更新人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：LITE\n  updatedBy                         String              @map(\"updated_by\") @db.VarChar(15)\n  /// 過帳時間（POSTED 才有）；啟用最低需求版本：LITE\n  postedAt                          DateTime?           @map(\"posted_at\")\n  /// 過帳人（POSTED 才有）；啟用最低需求版本：LITE\n  postedBy                          String?             @map(\"posted_by\") @db.VarChar(15)\n  /// 作廢時間；啟用最低需求版本：LITE\n  voidedAt                          DateTime?           @map(\"voided_at\")\n  /// 作廢人（使用者 ID）；啟用最低需求版本：LITE\n  voidedBy                          String?             @map(\"voided_by\") @db.VarChar(15)\n  /// 盤點範圍明細（scope_type=P時填入），例如：指定料號清單、庫位代碼、零件族群代碼。；啟用最低需求版本：LITE-CORE\n  scopeDetail                       String?             @map(\"scope_detail\") @db.VarChar(200)\n  /// 盤點開始時間（點擊開始盤點時記錄，計時器啟動）。；啟用最低需求版本：LITE-CORE\n  startedAt                         DateTime?           @map(\"started_at\")\n  /// 負責人審核差異報告核准時間。；啟用最低需求版本：LITE-CORE\n  approvedAt                        DateTime?           @map(\"approved_at\")\n  /// 負責人核准人（使用者ID）。；啟用最低需求版本：LITE-CORE\n  approvedBy                        String?             @map(\"approved_by\") @db.VarChar(15)\n  tenant                            Nx99Tenant          @relation(\"R_Nx03StockTake_tenantId\", fields: [tenantId], references: [id])\n  warehouse                         Nx01Warehouse       @relation(\"R_Nx03StockTake_warehouseId\", fields: [warehouseId], references: [id])\n  rev_Nx03StockTakeItem_stockTakeId Nx03StockTakeItem[] @relation(\"R_Nx03StockTakeItem_stockTakeId\")\n\n  @@unique([docNo])\n  @@map(\"nx03_stock_take\")\n}\n\n/// =======================================================\n/// Nx03StockTakeItem — DB table `nx03_stock_take_item`\n/// =======================================================\nmodel Nx03StockTakeItem {\n  /// [NX03]+[STTI]+[7碼流水號]，EX : NX03STTI0000001；啟用最低需求版本：LITE\n  id            String        @id @default(dbgenerated(\"gen_nx03_stock_take_item_id()\")) @db.VarChar(15)\n  /// 對應盤點單表頭 ID；啟用最低需求版本：LITE\n  stockTakeId   String        @map(\"stock_take_id\") @db.VarChar(15)\n  /// 明細行號（1,2,3…）；啟用最低需求版本：LITE\n  lineNo        Int           @default(1) @map(\"line_no\")\n  /// 零件 ID；啟用最低需求版本：LITE\n  partId        String        @map(\"part_id\") @db.VarChar(15)\n  /// 零件料號快照；啟用最低需求版本：LITE\n  partNo        String        @map(\"part_no\") @db.VarChar(50)\n  /// 零件名稱快照；啟用最低需求版本：LITE\n  partName      String        @map(\"part_name\") @db.VarChar(200)\n  /// 盤點倉庫 ID（通常等於表頭倉庫）；啟用最低需求版本：LITE\n  warehouseId   String        @map(\"warehouse_id\") @db.VarChar(15)\n  /// 盤點庫位 ID；啟用最低需求版本：LITE\n  locationId    String        @map(\"location_id\") @db.VarChar(15)\n  /// 系統數量（盤點當下抓 balance.on_hand_qty 快照）；啟用最低需求版本：LITE\n  systemQty     Decimal       @default(0) @map(\"system_qty\") @db.Decimal(14, 4)\n  /// 盤點數量（使用者輸入）；啟用最低需求版本：LITE\n  countedQty    Decimal       @default(0) @map(\"counted_qty\") @db.Decimal(14, 4)\n  /// 差異數量（counted_qty - system_qty）；啟用最低需求版本：LITE\n  diffQty       Decimal       @default(0) @map(\"diff_qty\") @db.Decimal(14, 4)\n  /// 調整成本（預設抓 balance.avg_cost 快照）；啟用最低需求版本：LITE\n  unitCost      Decimal       @default(0) @map(\"unit_cost\") @db.Decimal(14, 4)\n  /// 差異金額（abs(diff_qty) * unit_cost，或 diff_qty * unit_cost 由你決定）；啟用最低需求版本：LITE\n  diffCost      Decimal       @default(0) @map(\"diff_cost\") @db.Decimal(14, 2)\n  /// 調整類型。( I=IN, O=OUT, N=NONE )  ※ diff_qty=0 時 NONE）；啟用最低需求版本：LITE\n  adjustType    String        @default(\"N\") @map(\"adjust_type\") @db.VarChar(1)\n  /// 狀態。( O=OPEN, P=POSTED, S=SKIPPED )；啟用最低需求版本：LITE\n  status        String        @default(\"O\") @db.VarChar(1)\n  /// 備註；啟用最低需求版本：LITE\n  remark        String?       @db.VarChar(200)\n  /// 建立時間。；啟用最低需求版本：LITE\n  createdAt     DateTime      @default(now()) @map(\"created_at\")\n  /// 建立人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：LITE\n  createdBy     String        @map(\"created_by\") @db.VarChar(15)\n  /// 更新時間。；啟用最低需求版本：LITE\n  updatedAt     DateTime      @updatedAt @map(\"updated_at\")\n  /// 更新人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：LITE\n  updatedBy     String        @map(\"updated_by\") @db.VarChar(15)\n  /// 每筆實際填入時間點（即時差異計算的關鍵欄位）。系統在此時間點計算該料號的真實差異，避免盤點期間進出貨造成的誤差。；啟用最低需求版本：LITE-CORE\n  countedAt     DateTime?     @map(\"counted_at\")\n  /// 差異處置方式（W=報廢/R=零件重組/D=瑕疵品/U=中古件）。diff_qty≠0時必填。；啟用最低需求版本：LITE-CORE\n  disposeType   String?       @map(\"dispose_type\") @db.VarChar(1)\n  /// 處置說明（diff_qty≠0時必填）。例：外觀損壞無法銷售、拆解後可利用零件。；啟用最低需求版本：LITE-CORE\n  disposeRemark String?       @map(\"dispose_remark\") @db.VarChar(200)\n  stockTake     Nx03StockTake @relation(\"R_Nx03StockTakeItem_stockTakeId\", fields: [stockTakeId], references: [id])\n  part          Nx01Part      @relation(\"R_Nx03StockTakeItem_partId\", fields: [partId], references: [id])\n  warehouse     Nx01Warehouse @relation(\"R_Nx03StockTakeItem_warehouseId\", fields: [warehouseId], references: [id])\n  location      Nx01Location  @relation(\"R_Nx03StockTakeItem_locationId\", fields: [locationId], references: [id])\n\n  @@map(\"nx03_stock_take_item\")\n}\n\n/// =======================================================\n/// Nx03Inbound — DB table `nx03_inbound`\n/// =======================================================\nmodel Nx03Inbound {\n  /// [NX03]+[IBHT]+[7碼流水號]，EX : NX03IBHT0000001；啟用最低需求版本：LITE-CORE\n  id                            String            @id @default(dbgenerated(\"gen_nx03_inbound_id()\")) @db.VarChar(15)\n  tenantId                      String            @map(\"tenant_id\") @db.VarChar(15)\n  docNo                         String            @map(\"doc_no\") @db.VarChar(30)\n  warehouseId                   String            @map(\"warehouse_id\") @db.VarChar(15)\n  inboundDate                   DateTime          @map(\"inbound_date\") @db.Date\n  status                        String            @default(\"DRAFT\") @db.VarChar(30)\n  remark                        String?           @db.VarChar(200)\n  voidedAt                      DateTime?         @map(\"voided_at\")\n  voidedBy                      String?           @map(\"voided_by\") @db.VarChar(15)\n  postedAt                      DateTime?         @map(\"posted_at\")\n  postedBy                      String?           @map(\"posted_by\") @db.VarChar(15)\n  createdAt                     DateTime          @default(now()) @map(\"created_at\")\n  createdBy                     String            @map(\"created_by\") @db.VarChar(15)\n  updatedAt                     DateTime          @updatedAt @map(\"updated_at\")\n  updatedBy                     String            @map(\"updated_by\") @db.VarChar(15)\n  tenant                        Nx99Tenant        @relation(\"R_Nx03Inbound_tenantId\", fields: [tenantId], references: [id])\n  warehouse                     Nx01Warehouse     @relation(\"R_Nx03Inbound_warehouseId\", fields: [warehouseId], references: [id])\n  rev_Nx03InboundItem_inboundId Nx03InboundItem[] @relation(\"R_Nx03InboundItem_inboundId\")\n\n  @@unique([docNo])\n  @@map(\"nx03_inbound\")\n}\n\n/// =======================================================\n/// Nx03InboundItem — DB table `nx03_inbound_item`\n/// =======================================================\nmodel Nx03InboundItem {\n  /// [NX03]+[IBIT]+[7碼流水號]，EX : NX03IBIT0000001；啟用最低需求版本：LITE-CORE\n  id         String       @id @default(dbgenerated(\"gen_nx03_inbound_item_id()\")) @db.VarChar(15)\n  inboundId  String       @map(\"inbound_id\") @db.VarChar(15)\n  lineNo     Int          @default(1) @map(\"line_no\")\n  partId     String       @map(\"part_id\") @db.VarChar(15)\n  partNo     String       @map(\"part_no\") @db.VarChar(50)\n  partName   String       @map(\"part_name\") @db.VarChar(200)\n  locationId String       @map(\"location_id\") @db.VarChar(15)\n  qty        Decimal      @default(0) @db.Decimal(14, 4)\n  unitCost   Decimal      @default(0) @map(\"unit_cost\") @db.Decimal(14, 4)\n  lineAmount Decimal      @default(0) @map(\"line_amount\") @db.Decimal(14, 2)\n  remark     String?      @db.VarChar(200)\n  createdAt  DateTime     @default(now()) @map(\"created_at\")\n  createdBy  String       @map(\"created_by\") @db.VarChar(15)\n  updatedAt  DateTime     @updatedAt @map(\"updated_at\")\n  updatedBy  String       @map(\"updated_by\") @db.VarChar(15)\n  inbound    Nx03Inbound  @relation(\"R_Nx03InboundItem_inboundId\", fields: [inboundId], references: [id], onDelete: Cascade)\n  part       Nx01Part     @relation(\"R_Nx03InboundItem_partId\", fields: [partId], references: [id])\n  location   Nx01Location @relation(\"R_Nx03InboundItem_locationId\", fields: [locationId], references: [id])\n\n  @@map(\"nx03_inbound_item\")\n}\n\n/// =======================================================\n/// Nx03Outbound — DB table `nx03_outbound`\n/// =======================================================\nmodel Nx03Outbound {\n  /// [NX03]+[OBHT]+[7碼流水號]，EX : NX03OBHT0000001；啟用最低需求版本：LITE-CORE\n  id                              String             @id @default(dbgenerated(\"gen_nx03_outbound_id()\")) @db.VarChar(15)\n  tenantId                        String             @map(\"tenant_id\") @db.VarChar(15)\n  docNo                           String             @map(\"doc_no\") @db.VarChar(30)\n  warehouseId                     String             @map(\"warehouse_id\") @db.VarChar(15)\n  outboundDate                    DateTime           @map(\"outbound_date\") @db.Date\n  status                          String             @default(\"DRAFT\") @db.VarChar(30)\n  remark                          String?            @db.VarChar(200)\n  voidedAt                        DateTime?          @map(\"voided_at\")\n  voidedBy                        String?            @map(\"voided_by\") @db.VarChar(15)\n  shippedAt                       DateTime?          @map(\"shipped_at\")\n  shippedBy                       String?            @map(\"shipped_by\") @db.VarChar(15)\n  createdAt                       DateTime           @default(now()) @map(\"created_at\")\n  createdBy                       String             @map(\"created_by\") @db.VarChar(15)\n  updatedAt                       DateTime           @updatedAt @map(\"updated_at\")\n  updatedBy                       String             @map(\"updated_by\") @db.VarChar(15)\n  tenant                          Nx99Tenant         @relation(\"R_Nx03Outbound_tenantId\", fields: [tenantId], references: [id])\n  warehouse                       Nx01Warehouse      @relation(\"R_Nx03Outbound_warehouseId\", fields: [warehouseId], references: [id])\n  rev_Nx03OutboundItem_outboundId Nx03OutboundItem[] @relation(\"R_Nx03OutboundItem_outboundId\")\n\n  @@unique([docNo])\n  @@map(\"nx03_outbound\")\n}\n\n/// =======================================================\n/// Nx03OutboundItem — DB table `nx03_outbound_item`\n/// =======================================================\nmodel Nx03OutboundItem {\n  /// [NX03]+[OBIT]+[7碼流水號]，EX : NX03OBIT0000001；啟用最低需求版本：LITE-CORE\n  id         String       @id @default(dbgenerated(\"gen_nx03_outbound_item_id()\")) @db.VarChar(15)\n  outboundId String       @map(\"outbound_id\") @db.VarChar(15)\n  lineNo     Int          @default(1) @map(\"line_no\")\n  partId     String       @map(\"part_id\") @db.VarChar(15)\n  partNo     String       @map(\"part_no\") @db.VarChar(50)\n  partName   String       @map(\"part_name\") @db.VarChar(200)\n  locationId String       @map(\"location_id\") @db.VarChar(15)\n  qty        Decimal      @default(0) @db.Decimal(14, 4)\n  unitCost   Decimal      @default(0) @map(\"unit_cost\") @db.Decimal(14, 4)\n  lineAmount Decimal      @default(0) @map(\"line_amount\") @db.Decimal(14, 2)\n  remark     String?      @db.VarChar(200)\n  createdAt  DateTime     @default(now()) @map(\"created_at\")\n  createdBy  String       @map(\"created_by\") @db.VarChar(15)\n  updatedAt  DateTime     @updatedAt @map(\"updated_at\")\n  updatedBy  String       @map(\"updated_by\") @db.VarChar(15)\n  outbound   Nx03Outbound @relation(\"R_Nx03OutboundItem_outboundId\", fields: [outboundId], references: [id], onDelete: Cascade)\n  part       Nx01Part     @relation(\"R_Nx03OutboundItem_partId\", fields: [partId], references: [id])\n  location   Nx01Location @relation(\"R_Nx03OutboundItem_locationId\", fields: [locationId], references: [id])\n\n  @@map(\"nx03_outbound_item\")\n}\n\n/// =======================================================\n/// Nx04Co — DB table `nx04_co`（客戶訂單，Phase 0 D3 新建）\n/// =======================================================\nmodel Nx04Co {\n  /// [NX04]+[COHD]+[7碼流水號]，EX : NX04COHD0000001；啟用最低需求版本：LITE-CORE\n  id                  String        @id @default(dbgenerated(\"gen_nx04_co_id()\")) @db.VarChar(15)\n  /// 租戶 ID（外鍵）。；啟用最低需求版本：LITE-CORE\n  tenantId            String        @map(\"tenant_id\") @db.VarChar(15)\n  /// 對應倉庫 ID（FK nx01_warehouse）。；啟用最低需求版本：LITE-CORE\n  warehouseId         String        @map(\"warehouse_id\") @db.VarChar(15)\n  /// 客戶訂單號（唯一），[CO]+[年月]+[倉別]+[5碼流水號]，EX：CO-202604-Z01-00001；啟用最低需求版本：LITE-CORE\n  docNo               String        @map(\"doc_no\") @db.VarChar(20)\n  /// 客戶訂單日期。；啟用最低需求版本：LITE-CORE\n  coDate              DateTime      @map(\"co_date\") @db.Date\n  /// 客戶 ID（FK nx01_partner，partner_type=C）。；啟用最低需求版本：LITE-CORE\n  customerId          String        @map(\"customer_id\") @db.VarChar(15)\n  /// 零件 ID（FK nx01_part）。；啟用最低需求版本：LITE-CORE\n  partId              String        @map(\"part_id\") @db.VarChar(15)\n  /// 預期數量。；啟用最低需求版本：LITE-CORE\n  qty                 Decimal       @db.Decimal(14, 4)\n  /// 預期完成日期（選填）。；啟用最低需求版本：LITE-CORE\n  expectedFulfillDate DateTime?     @map(\"expected_fulfill_date\") @db.Date\n  /// 狀態（P=待補/F=已補完/E=過期/V=作廢）。；啟用最低需求版本：LITE-CORE\n  status              String        @default(\"P\") @db.VarChar(1)\n  /// 來源銷貨明細 ID（必填，反向追蹤）。；啟用最低需求版本：LITE-CORE\n  sourceSoItemId      String        @map(\"source_so_item_id\") @db.VarChar(15)\n  /// 備註。；啟用最低需求版本：LITE-CORE\n  remark              String?       @db.VarChar(200)\n  /// 建立時間。；啟用最低需求版本：LITE-CORE\n  createdAt           DateTime      @default(now()) @map(\"created_at\")\n  /// 建立人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）。；啟用最低需求版本:LITE-CORE\n  createdBy           String        @map(\"created_by\") @db.VarChar(15)\n  /// 更新時間。；啟用最低需求版本：LITE-CORE\n  updatedAt           DateTime      @updatedAt @map(\"updated_at\")\n  /// 更新人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：LITE-CORE\n  updatedBy           String        @map(\"updated_by\") @db.VarChar(15)\n  tenant              Nx99Tenant    @relation(\"R_Nx04Co_tenantId\", fields: [tenantId], references: [id])\n  warehouse           Nx01Warehouse @relation(\"R_Nx04Co_warehouseId\", fields: [warehouseId], references: [id])\n  customer            Nx01Partner   @relation(\"R_Nx04Co_customerId\", fields: [customerId], references: [id])\n  part                Nx01Part      @relation(\"R_Nx04Co_partId\", fields: [partId], references: [id])\n  sourceSoItem        Nx04SoItem    @relation(\"R_Nx04Co_sourceSoItemId\", fields: [sourceSoItemId], references: [id])\n  rev_Nx04SoItem_coId Nx04SoItem[]  @relation(\"R_Nx04SoItem_coId\")\n\n  @@unique([docNo])\n  @@index([tenantId, customerId])\n  @@index([tenantId, status])\n  @@index([tenantId, sourceSoItemId])\n  @@map(\"nx04_co\")\n}\n\n/// =======================================================\n/// Nx04Quote — DB table `nx04_quote`\n/// =======================================================\nmodel Nx04Quote {\n  /// [NX04]+[QTHD]+[7碼流水號]，EX : NX04QTHD0000001；啟用最低需求版本：LITE-CORE\n  id                        String             @id @default(dbgenerated(\"gen_nx04_quote_id()\")) @db.VarChar(15)\n  /// 租戶 ID（外鍵）。；啟用最低需求版本：LITE-CORE\n  tenantId                  String             @map(\"tenant_id\") @db.VarChar(15)\n  /// 報價倉庫ID，影響單號產生（FK nx01_warehouse）。；啟用最低需求版本：LITE-CORE\n  warehouseId               String             @map(\"warehouse_id\") @db.VarChar(15)\n  /// 報價單號（唯一），[QT]+[年月]+[倉別]+[5碼流水號]，EX：QT-202604-Z01-00001；啟用最低需求版本：LITE-CORE\n  docNo                     String             @map(\"doc_no\") @db.VarChar(30)\n  /// 報價日期。；啟用最低需求版本：LITE-CORE\n  quoteDate                 DateTime           @map(\"quote_date\") @db.Date\n  /// 客戶ID（FK nx01_partner，partner_type=C）。；啟用最低需求版本：LITE-CORE\n  customerId                String             @map(\"customer_id\") @db.VarChar(15)\n  /// 客戶等級ID快照（報價時帶入）。；啟用最低需求版本：LITE-CORE\n  customerGradeId           String?            @map(\"customer_grade_id\") @db.VarChar(15)\n  /// 報價有效期限，過期後不得轉銷貨單。；啟用最低需求版本：LITE-CORE\n  validUntil                DateTime?          @map(\"valid_until\") @db.Date\n  /// 幣別ID（FK nx01_currency，預設TWD）。；啟用最低需求版本：LITE-CORE\n  currencyId                String             @default(\"TWD\") @map(\"currency_id\") @db.VarChar(15)\n  /// 小計（is_selected=TRUE的明細加總，未稅）。；啟用最低需求版本：LITE-CORE\n  subtotal                  Decimal            @default(0) @db.Decimal(14, 2)\n  /// 稅率（預設5.00）。；啟用最低需求版本：LITE-CORE\n  taxRate                   Decimal            @map(\"tax_rate\") @db.Decimal(5, 2)\n  /// 稅額。；啟用最低需求版本：LITE-CORE\n  taxAmount                 Decimal            @default(0) @map(\"tax_amount\") @db.Decimal(14, 2)\n  /// 總額（subtotal + tax_amount）。；啟用最低需求版本：LITE-CORE\n  totalAmount               Decimal            @default(0) @map(\"total_amount\") @db.Decimal(14, 2)\n  /// 狀態（DRAFT / SENT / ACCEPTED / REJECTED / EXPIRED / CANCELLED）。；啟用最低需求版本：LITE-CORE\n  status                    String             @default(\"DRAFT\") @db.VarChar(30)\n  /// 備註。；啟用最低需求版本：LITE-CORE\n  remark                    String?            @db.VarChar(200)\n  /// 作廢時間。；啟用最低需求版本：LITE-CORE\n  voidedAt                  DateTime?          @map(\"voided_at\")\n  /// 作廢人（使用者ID）。；啟用最低需求版本：LITE-CORE\n  voidedBy                  String?            @map(\"voided_by\") @db.VarChar(15)\n  /// 作廢原因（必填）。；啟用最低需求版本：LITE-CORE\n  voidReason                String?            @map(\"void_reason\") @db.VarChar(200)\n  /// 建立時間。；啟用最低需求版本：LITE-CORE\n  createdAt                 DateTime           @default(now()) @map(\"created_at\")\n  /// 建立人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：LITE-CORE\n  createdBy                 String             @map(\"created_by\") @db.VarChar(15)\n  /// 更新時間。；啟用最低需求版本：LITE-CORE\n  updatedAt                 DateTime           @updatedAt @map(\"updated_at\")\n  /// 更新人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：LITE-CORE\n  updatedBy                 String             @map(\"updated_by\") @db.VarChar(15)\n  /// 來源詢價單ID（可空，無庫存走同行調貨詢價流程時填入，FK nx02_rfq）。；啟用最低需求版本：LITE-CORE\n  rfqId                     String?            @map(\"rfq_id\") @db.VarChar(15)\n  tenant                    Nx99Tenant         @relation(\"R_Nx04Quote_tenantId\", fields: [tenantId], references: [id])\n  warehouse                 Nx01Warehouse      @relation(\"R_Nx04Quote_warehouseId\", fields: [warehouseId], references: [id])\n  customer                  Nx01Partner        @relation(\"R_Nx04Quote_customerId\", fields: [customerId], references: [id])\n  customerGrade             Nx01CustomerGrade? @relation(\"R_Nx04Quote_customerGradeId\", fields: [customerGradeId], references: [id])\n  currency                  Nx01Currency       @relation(\"R_Nx04Quote_currencyId\", fields: [currencyId], references: [id])\n  rfq                       Nx02Rfq?           @relation(\"R_Nx04Quote_rfqId\", fields: [rfqId], references: [id])\n  rev_Nx04QuoteItem_quoteId Nx04QuoteItem[]    @relation(\"R_Nx04QuoteItem_quoteId\")\n  rev_Nx04So_quoteId        Nx04So[]           @relation(\"R_Nx04So_quoteId\")\n\n  @@unique([docNo])\n  @@map(\"nx04_quote\")\n}\n\n/// =======================================================\n/// Nx04QuoteItem — DB table `nx04_quote_item`\n/// =======================================================\nmodel Nx04QuoteItem {\n  /// [NX04]+[QTIT]+[7碼流水號]，EX : NX04QTIT0000001；啟用最低需求版本：LITE-CORE\n  id                         String            @id @default(dbgenerated(\"gen_nx04_quote_item_id()\")) @db.VarChar(15)\n  /// 對應報價單表頭ID（FK nx04_quote）。；啟用最低需求版本：LITE-CORE\n  quoteId                    String            @map(\"quote_id\") @db.VarChar(15)\n  /// 明細行號（1,2,3…）。；啟用最低需求版本：LITE-CORE\n  lineNo                     Int               @map(\"line_no\")\n  /// 選項群組號碼，同一客戶詢問對應多個料號時使用相同group_no（如原廠+副廠選項）。NULL表示無多選項。；啟用最低需求版本：LITE-CORE\n  groupNo                    Int?              @map(\"group_no\")\n  /// 零件ID（FK nx01_part）。；啟用最低需求版本：LITE-CORE\n  partId                     String            @map(\"part_id\") @db.VarChar(15)\n  /// 零件料號快照。；啟用最低需求版本：LITE-CORE\n  partNo                     String            @map(\"part_no\") @db.VarChar(50)\n  /// 零件名稱快照。；啟用最低需求版本：LITE-CORE\n  partName                   String            @map(\"part_name\") @db.VarChar(200)\n  /// 報價數量。；啟用最低需求版本：LITE-CORE\n  qty                        Decimal           @db.Decimal(14, 4)\n  /// 報價單價（業務填入）。；啟用最低需求版本：LITE-CORE\n  unitPrice                  Decimal           @default(0) @map(\"unit_price\") @db.Decimal(14, 4)\n  /// 最低售價快照（依客戶等級計算，成本×毛利%），供前端警示用。；啟用最低需求版本：LITE-CORE\n  minPrice                   Decimal?          @map(\"min_price\") @db.Decimal(14, 4)\n  /// 折扣代碼ID（選填，FK nx01_discount_code）。；啟用最低需求版本：LITE-CORE\n  discountCodeId             String?           @map(\"discount_code_id\") @db.VarChar(15)\n  /// 明細金額（qty × unit_price）。is_selected=FALSE時不計入表頭小計。；啟用最低需求版本：LITE-CORE\n  lineAmount                 Decimal           @default(0) @map(\"line_amount\") @db.Decimal(14, 2)\n  /// 客戶是否選擇此料號（同group_no多選項中，客戶確認選哪筆）。FALSE的明細不計入小計、不轉銷貨單。；啟用最低需求版本：LITE-CORE\n  isSelected                 Boolean           @default(true) @map(\"is_selected\")\n  /// 低於最低售價原因（unit_price < min_price時必填，自動記錄並倒扣業績）。；啟用最低需求版本：LITE-CORE\n  belowMinReason             String?           @map(\"below_min_reason\") @db.VarChar(200)\n  /// 已轉銷貨單數量（支援同一報價單分批轉單，不可超過qty）。；啟用最低需求版本：LITE-CORE\n  transferredQty             Decimal           @default(0) @map(\"transferred_qty\") @db.Decimal(14, 4)\n  /// 備註。；啟用最低需求版本：LITE-CORE\n  remark                     String?           @db.VarChar(200)\n  /// 建立時間。；啟用最低需求版本：LITE-CORE\n  createdAt                  DateTime          @default(now()) @map(\"created_at\")\n  /// 建立人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）。；啟用最低需求版本：LITE-CORE\n  createdBy                  String            @map(\"created_by\") @db.VarChar(15)\n  /// 更新時間。；啟用最低需求版本：LITE-CORE\n  updatedAt                  DateTime          @updatedAt @map(\"updated_at\")\n  /// 更新人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：LITE-CORE\n  updatedBy                  String            @map(\"updated_by\") @db.VarChar(15)\n  quote                      Nx04Quote         @relation(\"R_Nx04QuoteItem_quoteId\", fields: [quoteId], references: [id])\n  part                       Nx01Part          @relation(\"R_Nx04QuoteItem_partId\", fields: [partId], references: [id])\n  discountCode               Nx01DiscountCode? @relation(\"R_Nx04QuoteItem_discountCodeId\", fields: [discountCodeId], references: [id])\n  rev_Nx04SoItem_quoteItemId Nx04SoItem[]      @relation(\"R_Nx04SoItem_quoteItemId\")\n\n  @@map(\"nx04_quote_item\")\n}\n\n/// =======================================================\n/// Nx04So — DB table `nx04_so`\n/// =======================================================\nmodel Nx04So {\n  /// [NX04]+[SOHD]+[7碼流水號]，EX : NX04SOHD0000001；啟用最低需求版本：LITE-CORE\n  id                     String         @id @default(dbgenerated(\"gen_nx04_so_id()\")) @db.VarChar(15)\n  /// 租戶 ID（外鍵）。；啟用最低需求版本：LITE-CORE\n  tenantId               String         @map(\"tenant_id\") @db.VarChar(15)\n  /// 出貨倉庫ID（FK nx01_warehouse）。；啟用最低需求版本：LITE-CORE\n  warehouseId            String         @map(\"warehouse_id\") @db.VarChar(15)\n  /// 銷貨單號（唯一），[SO]+[年月]+[倉別]+[5碼流水號]，EX：SO-202604-Z01-00001；啟用最低需求版本：LITE-CORE\n  docNo                  String         @map(\"doc_no\") @db.VarChar(30)\n  /// 銷貨日期。；啟用最低需求版本：LITE-CORE\n  soDate                 DateTime       @map(\"so_date\") @db.Date\n  /// 客戶ID（FK nx01_partner，partner_type=C）。；啟用最低需求版本：LITE-CORE\n  customerId             String         @map(\"customer_id\") @db.VarChar(15)\n  /// 來源報價單ID（FK nx04_quote，可空=即時報價直接開單）。；啟用最低需求版本：LITE-CORE\n  quoteId                String?        @map(\"quote_id\") @db.VarChar(15)\n  /// 出貨方式（D=配送/P=自取/C=寄貨）。影響後續流程分流與AR產生時機。；啟用最低需求版本：LITE-CORE\n  deliveryType           String         @map(\"delivery_type\") @db.VarChar(1)\n  /// @deprecated 2026-04-25 (Phase 0 D3)：改由 line item 的 transfer_source_type 決定；header 此欄無語意。trigger 將防寫入。\n  /// 出貨來源（S=本倉庫存/O=他倉/T=調撥/G=同行調貨/M=混合/B=客訂預約）。；啟用最低需求版本：LITE-CORE\n  sourceType             String         @default(\"S\") @map(\"source_type\") @db.VarChar(1)\n  /// 配送地址（delivery_type=D時必填）。；啟用最低需求版本：LITE-CORE\n  deliveryAddress        String?        @map(\"delivery_address\") @db.VarChar(200)\n  /// 幣別ID（FK nx01_currency）。；啟用最低需求版本：LITE-CORE\n  currencyId             String         @default(\"TWD\") @map(\"currency_id\") @db.VarChar(15)\n  /// 小計（明細加總，未稅）。；啟用最低需求版本：LITE-CORE\n  subtotal               Decimal        @default(0) @db.Decimal(14, 2)\n  /// 稅率（預設5.00）。；啟用最低需求版本：LITE-CORE\n  taxRate                Decimal        @map(\"tax_rate\") @db.Decimal(5, 2)\n  /// 稅額。；啟用最低需求版本：LITE-CORE\n  taxAmount              Decimal        @default(0) @map(\"tax_amount\") @db.Decimal(14, 2)\n  /// 總額（subtotal + tax_amount）。；啟用最低需求版本：LITE-CORE\n  totalAmount            Decimal        @default(0) @map(\"total_amount\") @db.Decimal(14, 2)\n  /// 狀態（DRAFT / CONFIRMED / PICKING / SHIPPED / INVOICED / CANCELLED）。；啟用最低需求版本：LITE-CORE\n  status                 String         @default(\"DRAFT\") @db.VarChar(30)\n  /// 付款條件（快照自nx01_partner.payment_term）。影響AR產生時機。；啟用最低需求版本：LITE-CORE\n  paymentTerm            String         @default(\"NET30\") @map(\"payment_term\") @db.VarChar(10)\n  /// 預計出貨日（選填）。；啟用最低需求版本：LITE-CORE\n  expectedDeliveryDate   DateTime?      @map(\"expected_delivery_date\") @db.Date\n  /// 取消原因（status=X時必填）。；啟用最低需求版本：LITE-CORE\n  cancelReason           String?        @map(\"cancel_reason\") @db.VarChar(200)\n  /// 取消時間。；啟用最低需求版本：LITE-CORE\n  cancelledAt            DateTime?      @map(\"cancelled_at\")\n  /// 取消人（使用者ID）。；啟用最低需求版本：LITE-CORE\n  cancelledBy            String?        @map(\"cancelled_by\") @db.VarChar(15)\n  /// 完成時間（status=C時填入）。；啟用最低需求版本：LITE-CORE\n  completedAt            DateTime?      @map(\"completed_at\")\n  /// 備註。；啟用最低需求版本：LITE-CORE\n  remark                 String?        @db.VarChar(200)\n  /// 建立時間。；啟用最低需求版本：LITE-CORE\n  createdAt              DateTime       @default(now()) @map(\"created_at\")\n  /// 建立人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：LITE-CORE\n  createdBy              String         @map(\"created_by\") @db.VarChar(15)\n  /// 更新時間。；啟用最低需求版本：LITE-CORE\n  updatedAt              DateTime       @updatedAt @map(\"updated_at\")\n  /// 更新人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：LITE-CORE\n  updatedBy              String         @map(\"updated_by\") @db.VarChar(15)\n  tenant                 Nx99Tenant     @relation(\"R_Nx04So_tenantId\", fields: [tenantId], references: [id])\n  warehouse              Nx01Warehouse  @relation(\"R_Nx04So_warehouseId\", fields: [warehouseId], references: [id])\n  customer               Nx01Partner    @relation(\"R_Nx04So_customerId\", fields: [customerId], references: [id])\n  quote                  Nx04Quote?     @relation(\"R_Nx04So_quoteId\", fields: [quoteId], references: [id])\n  currency               Nx01Currency   @relation(\"R_Nx04So_currencyId\", fields: [currencyId], references: [id])\n  rev_Nx03PkItem_refSoId Nx03PkItem[]   @relation(\"R_Nx03PkItem_refSoId\")\n  rev_Nx03St_refSoId     Nx03St[]       @relation(\"R_Nx03St_refSoId\")\n  rev_Nx04SoItem_soId    Nx04SoItem[]   @relation(\"R_Nx04SoItem_soId\")\n  rev_Nx04Sr_soId        Nx04Sr[]       @relation(\"R_Nx04Sr_soId\")\n  rev_Nx05ArLedger_soId  Nx05ArLedger[] @relation(\"R_Nx05ArLedger_soId\")\n  rev_Nx06Dn_sourceSoId  Nx06Dn[]       @relation(\"R_Nx06Dn_sourceSoId\")\n\n  @@unique([docNo])\n  @@map(\"nx04_so\")\n}\n\n/// =======================================================\n/// Nx04SoItem — DB table `nx04_so_item`\n/// =======================================================\nmodel Nx04SoItem {\n  /// [NX04]+[SOIT]+[7碼流水號]，EX : NX04SOIT0000001；啟用最低需求版本：LITE-CORE\n  id                            String            @id @default(dbgenerated(\"gen_nx04_so_item_id()\")) @db.VarChar(15)\n  /// 對應銷貨單表頭ID（FK nx04_so）。；啟用最低需求版本：LITE-CORE\n  soId                          String            @map(\"so_id\") @db.VarChar(15)\n  /// 來源報價明細ID（可空，即時報價時無來源）。；啟用最低需求版本：LITE-CORE\n  quoteItemId                   String?           @map(\"quote_item_id\") @db.VarChar(15)\n  /// 明細行號（1,2,3…）。；啟用最低需求版本：LITE-CORE\n  lineNo                        Int               @map(\"line_no\")\n  /// 零件ID（FK nx01_part）。；啟用最低需求版本：LITE-CORE\n  partId                        String            @map(\"part_id\") @db.VarChar(15)\n  /// 零件料號快照。；啟用最低需求版本：LITE-CORE\n  partNo                        String            @map(\"part_no\") @db.VarChar(50)\n  /// 零件名稱快照。；啟用最低需求版本：LITE-CORE\n  partName                      String            @map(\"part_name\") @db.VarChar(200)\n  /// 出貨倉庫ID（FK nx01_warehouse，可與表頭不同支援跨倉銷售）。；啟用最低需求版本：LITE-CORE\n  warehouseId                   String            @map(\"warehouse_id\") @db.VarChar(15)\n  /// 出貨庫位ID（FK nx01_location）。；啟用最低需求版本：LITE-CORE\n  locationId                    String?           @map(\"location_id\") @db.VarChar(15)\n  /// 銷貨數量。；啟用最低需求版本：LITE-CORE\n  qty                           Decimal           @db.Decimal(14, 4)\n  /// 銷售單價。；啟用最低需求版本：LITE-CORE\n  unitPrice                     Decimal           @default(0) @map(\"unit_price\") @db.Decimal(14, 4)\n  /// 折扣代碼ID（選填，FK nx01_discount_code）。；啟用最低需求版本：LITE-CORE\n  discountCodeId                String?           @map(\"discount_code_id\") @db.VarChar(15)\n  /// 明細金額（qty × unit_price）。；啟用最低需求版本：LITE-CORE\n  lineAmount                    Decimal           @default(0) @map(\"line_amount\") @db.Decimal(14, 2)\n  /// 預留庫存數量（SO建立時立即寫入stock_balance.reserved_qty）。；啟用最低需求版本：LITE-CORE\n  reservedQty                   Decimal           @default(0) @map(\"reserved_qty\") @db.Decimal(14, 4)\n  /// 低於最低售價原因（必填）。；啟用最低需求版本：LITE-CORE\n  belowMinReason                String?           @map(\"below_min_reason\") @db.VarChar(200)\n  /// 備註。；啟用最低需求版本：LITE-CORE\n  remark                        String?           @db.VarChar(200)\n  /// 建立時間。；啟用最低需求版本：LITE-CORE\n  createdAt                     DateTime          @default(now()) @map(\"created_at\")\n  /// 建立人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）。；啟用最低需求版本：LITE-CORE\n  createdBy                     String            @map(\"created_by\") @db.VarChar(15)\n  /// 更新時間。；啟用最低需求版本：LITE-CORE\n  updatedAt                     DateTime          @updatedAt @map(\"updated_at\")\n  /// 更新人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：LITE-CORE\n  updatedBy                     String            @map(\"updated_by\") @db.VarChar(15)\n  /// @deprecated 2026-04-25 (Phase 0 D3)：改用 (transfer_status, fulfill_status) 雙段。trigger 仍會雙寫保留既有讀路徑相容。\n  /// 明細備貨狀態（WA=待調撥/TA=調撥中/WG=待調貨/TG=調貨中/WP=待撿貨/WD=待配送/ID=配送中/WT=待取貨/WB=待包貨/WS=待寄貨/C=已完成）。依出貨方式與備貨情況自動更新。；啟用最低需求版本：LITE-CORE\n  itemStatus                    String            @default(\"WP\") @map(\"item_status\") @db.VarChar(2)\n  /// 關聯調貨單ID（業務按Alt+T發起調貨後填入，FK nx02_ti）。；啟用最低需求版本：LITE-CORE\n  tiId                          String?           @map(\"ti_id\") @db.VarChar(15)\n  /// 關聯調撥單ID（系統偵測本倉庫存不足後自動建立，FK nx03_st）。；啟用最低需求版本：LITE-CORE\n  stId                          String?           @map(\"st_id\") @db.VarChar(15)\n  /// 補貨來源類型（S=本倉/T=自倉調撥/G=同行調貨/B=客戶訂單）。Phase 0 D3 新增。；啟用最低需求版本：LITE-CORE\n  transferSourceType            String            @default(\"S\") @map(\"transfer_source_type\") @db.VarChar(1)\n  /// 補貨進度（P=待補/I=補貨中/C=補貨完成）。雙段狀態之第一段。；啟用最低需求版本：LITE-CORE\n  transferStatus                String            @default(\"C\") @map(\"transfer_status\") @db.VarChar(1)\n  /// 出貨進度（W=等貨/PK=撿貨中/PL=包貨中/D=配送中/F=已送達）。雙段狀態之第二段。；啟用最低需求版本：LITE-CORE\n  fulfillStatus                 String            @default(\"W\") @map(\"fulfill_status\") @db.VarChar(2)\n  /// 關聯客戶訂單ID（transfer_source_type=B時填入，FK nx04_co）。；啟用最低需求版本：LITE-CORE\n  coId                          String?           @map(\"co_id\") @db.VarChar(15)\n  so                            Nx04So            @relation(\"R_Nx04SoItem_soId\", fields: [soId], references: [id])\n  quoteItem                     Nx04QuoteItem?    @relation(\"R_Nx04SoItem_quoteItemId\", fields: [quoteItemId], references: [id])\n  part                          Nx01Part          @relation(\"R_Nx04SoItem_partId\", fields: [partId], references: [id])\n  warehouse                     Nx01Warehouse     @relation(\"R_Nx04SoItem_warehouseId\", fields: [warehouseId], references: [id])\n  location                      Nx01Location?     @relation(\"R_Nx04SoItem_locationId\", fields: [locationId], references: [id])\n  discountCode                  Nx01DiscountCode? @relation(\"R_Nx04SoItem_discountCodeId\", fields: [discountCodeId], references: [id])\n  ti                            Nx02Ti?           @relation(\"R_Nx04SoItem_tiId\", fields: [tiId], references: [id])\n  st                            Nx03St?           @relation(\"R_Nx04SoItem_stId\", fields: [stId], references: [id])\n  co                            Nx04Co?           @relation(\"R_Nx04SoItem_coId\", fields: [coId], references: [id])\n  rev_Nx03PkItem_refSoItemId    Nx03PkItem[]      @relation(\"R_Nx03PkItem_refSoItemId\")\n  rev_Nx04SrItem_soItemId       Nx04SrItem[]      @relation(\"R_Nx04SrItem_soItemId\")\n  rev_Nx02TiItem_sourceSoItemId Nx02TiItem[]      @relation(\"R_Nx02TiItem_sourceSoItemId\")\n  rev_Nx03StItem_sourceSoItemId Nx03StItem[]      @relation(\"R_Nx03StItem_sourceSoItemId\")\n  rev_Nx04Co_sourceSoItemId     Nx04Co[]          @relation(\"R_Nx04Co_sourceSoItemId\")\n\n  @@index([partId, warehouseId], map: \"nx04_so_item_committed_lookup_idx\")\n  @@index([fulfillStatus], map: \"nx04_so_item_fulfill_status_idx\")\n  @@index([transferSourceType, stId], map: \"nx04_so_item_xfer_st_idx\")\n  @@index([transferSourceType, tiId], map: \"nx04_so_item_xfer_ti_idx\")\n  @@index([transferSourceType, coId], map: \"nx04_so_item_xfer_co_idx\")\n  @@map(\"nx04_so_item\")\n}\n\n/// =======================================================\n/// Nx04Sr — DB table `nx04_sr`\n/// =======================================================\nmodel Nx04Sr {\n  /// [NX04]+[SRHD]+[7碼流水號]，EX : NX04SRHD0000001；啟用最低需求版本：LITE-CORE\n  id                    String        @id @default(dbgenerated(\"gen_nx04_sr_id()\")) @db.VarChar(15)\n  /// 租戶 ID（外鍵）。；啟用最低需求版本：LITE-CORE\n  tenantId              String        @map(\"tenant_id\") @db.VarChar(15)\n  /// 退回倉庫ID（退回原出貨倉，FK nx01_warehouse）。；啟用最低需求版本：LITE-CORE\n  warehouseId           String        @map(\"warehouse_id\") @db.VarChar(15)\n  /// 銷退單號（唯一），[SR]+[年月]+[倉別]+[5碼流水號]，EX：SR-202604-Z01-00001；啟用最低需求版本：LITE-CORE\n  docNo                 String        @map(\"doc_no\") @db.VarChar(30)\n  /// 銷退日期。；啟用最低需求版本：LITE-CORE\n  srDate                DateTime      @map(\"sr_date\") @db.Date\n  /// 客戶ID（FK nx01_partner）。；啟用最低需求版本：LITE-CORE\n  customerId            String        @map(\"customer_id\") @db.VarChar(15)\n  /// 來源銷貨單ID（必填，FK nx04_so）。；啟用最低需求版本：LITE-CORE\n  soId                  String        @map(\"so_id\") @db.VarChar(15)\n  /// 退貨取件方式（S=客戶自行送回/C=外務順路取回/P=客戶自行寄回）。由外務組長在 NX07 決定並更新，NX04 建立時可預填供參考。；啟用最低需求版本：LITE-CORE\n  returnMethod          String        @map(\"return_method\") @db.VarChar(1)\n  /// 狀態（DRAFT / INSPECTING / POSTED / REJECTED / CANCELLED）。；啟用最低需求版本：LITE-CORE\n  status                String        @default(\"DRAFT\") @db.VarChar(30)\n  /// 退款小計（明細加總，未稅）。；啟用最低需求版本：LITE-CORE\n  subtotal              Decimal       @default(0) @db.Decimal(14, 2)\n  /// 稅率（預設5.00）。；啟用最低需求版本：LITE-CORE\n  taxRate               Decimal       @map(\"tax_rate\") @db.Decimal(5, 2)\n  /// 稅額。；啟用最低需求版本：LITE-CORE\n  taxAmount             Decimal       @default(0) @map(\"tax_amount\") @db.Decimal(14, 2)\n  /// 退款總額（subtotal + tax_amount）。；啟用最低需求版本：LITE-CORE\n  totalAmount           Decimal       @default(0) @map(\"total_amount\") @db.Decimal(14, 2)\n  /// 銷售組長核准時間。；啟用最低需求版本：LITE-CORE\n  approvedAt            DateTime?     @map(\"approved_at\")\n  /// 核准人（銷售組長，使用者ID）。；啟用最低需求版本：LITE-CORE\n  approvedBy            String?       @map(\"approved_by\") @db.VarChar(15)\n  /// 退件原因（銷售組長退件時填寫）。；啟用最低需求版本：LITE-CORE\n  rejectReason          String?       @map(\"reject_reason\") @db.VarChar(200)\n  /// 退貨收到時間（倉管專員確認收貨）。；啟用最低需求版本：LITE-CORE\n  receivedAt            DateTime?     @map(\"received_at\")\n  /// 收貨確認人（倉管專員，使用者ID）。；啟用最低需求版本：LITE-CORE\n  receivedBy            String?       @map(\"received_by\") @db.VarChar(15)\n  /// 備註。；啟用最低需求版本：LITE-CORE\n  remark                String?       @db.VarChar(200)\n  /// 建立時間。；啟用最低需求版本：LITE-CORE\n  createdAt             DateTime      @default(now()) @map(\"created_at\")\n  /// 建立人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：LITE-CORE\n  createdBy             String        @map(\"created_by\") @db.VarChar(15)\n  /// 更新時間。；啟用最低需求版本：LITE-CORE\n  updatedAt             DateTime      @updatedAt @map(\"updated_at\")\n  /// 更新人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：LITE-CORE\n  updatedBy             String        @map(\"updated_by\") @db.VarChar(15)\n  tenant                Nx99Tenant    @relation(\"R_Nx04Sr_tenantId\", fields: [tenantId], references: [id])\n  warehouse             Nx01Warehouse @relation(\"R_Nx04Sr_warehouseId\", fields: [warehouseId], references: [id])\n  customer              Nx01Partner   @relation(\"R_Nx04Sr_customerId\", fields: [customerId], references: [id])\n  so                    Nx04So        @relation(\"R_Nx04Sr_soId\", fields: [soId], references: [id])\n  rev_Nx04SrItem_srId   Nx04SrItem[]  @relation(\"R_Nx04SrItem_srId\")\n  rev_Nx06Dn_sourceSrId Nx06Dn[]      @relation(\"R_Nx06Dn_sourceSrId\")\n\n  @@unique([docNo])\n  @@map(\"nx04_sr\")\n}\n\n/// =======================================================\n/// Nx04SrItem — DB table `nx04_sr_item`\n/// =======================================================\nmodel Nx04SrItem {\n  /// [NX04]+[SRIT]+[7碼流水號]，EX : NX04SRIT0000001；啟用最低需求版本：LITE-CORE\n  id               String        @id @default(dbgenerated(\"gen_nx04_sr_item_id()\")) @db.VarChar(15)\n  /// 對應銷退單表頭ID（FK nx04_sr）。；啟用最低需求版本：LITE-CORE\n  srId             String        @map(\"sr_id\") @db.VarChar(15)\n  /// 來源銷貨明細ID（FK nx04_so_item）。；啟用最低需求版本：LITE-CORE\n  soItemId         String        @map(\"so_item_id\") @db.VarChar(15)\n  /// 明細行號（1,2,3…）。；啟用最低需求版本：LITE-CORE\n  lineNo           Int           @map(\"line_no\")\n  /// 零件ID（FK nx01_part）。；啟用最低需求版本：LITE-CORE\n  partId           String        @map(\"part_id\") @db.VarChar(15)\n  /// 零件料號快照。；啟用最低需求版本：LITE-CORE\n  partNo           String        @map(\"part_no\") @db.VarChar(50)\n  /// 零件名稱快照。；啟用最低需求版本：LITE-CORE\n  partName         String        @map(\"part_name\") @db.VarChar(200)\n  /// 退貨政策快照（F=自由/S=標準/R=限制/N=不可退/W=保固，從nx01_part帶入）。；啟用最低需求版本：LITE-CORE\n  returnPolicy     String        @map(\"return_policy\") @db.VarChar(1)\n  /// 退貨類型（N=一般退貨/E=業務通融）。；啟用最低需求版本：LITE-CORE\n  returnType       String        @default(\"N\") @map(\"return_type\") @db.VarChar(1)\n  /// 退貨原因（C=客戶不需要/D=商品有瑕疵/W=送錯料號/Q=送錯數量/O=其他）。；啟用最低需求版本：LITE-CORE\n  returnReason     String        @map(\"return_reason\") @db.VarChar(1)\n  /// 業務通融原因（return_type=E時必填）。；啟用最低需求版本：LITE-CORE\n  concessionReason String?       @map(\"concession_reason\") @db.VarChar(200)\n  /// 退貨數量（不可超過原始出貨數量）。；啟用最低需求版本：LITE-CORE\n  qty              Decimal       @db.Decimal(14, 4)\n  /// 退貨單價（從SO帶入）。；啟用最低需求版本：LITE-CORE\n  unitPrice        Decimal       @default(0) @map(\"unit_price\") @db.Decimal(14, 4)\n  /// 退款金額（qty × unit_price）。；啟用最低需求版本：LITE-CORE\n  lineAmount       Decimal       @default(0) @map(\"line_amount\") @db.Decimal(14, 2)\n  /// 退回庫位ID（倉管專員入庫時填入）。；啟用最低需求版本：LITE-CORE\n  locationId       String?       @map(\"location_id\") @db.VarChar(15)\n  /// 備註。；啟用最低需求版本：LITE-CORE\n  remark           String?       @db.VarChar(200)\n  /// 建立時間。；啟用最低需求版本：LITE-CORE\n  createdAt        DateTime      @default(now()) @map(\"created_at\")\n  /// 建立人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）。；啟用最低需求版本：LITE-CORE\n  createdBy        String        @map(\"created_by\") @db.VarChar(15)\n  /// 更新時間。；啟用最低需求版本：LITE-CORE\n  updatedAt        DateTime      @updatedAt @map(\"updated_at\")\n  /// 更新人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：LITE-CORE\n  updatedBy        String        @map(\"updated_by\") @db.VarChar(15)\n  sr               Nx04Sr        @relation(\"R_Nx04SrItem_srId\", fields: [srId], references: [id])\n  soItem           Nx04SoItem    @relation(\"R_Nx04SrItem_soItemId\", fields: [soItemId], references: [id])\n  part             Nx01Part      @relation(\"R_Nx04SrItem_partId\", fields: [partId], references: [id])\n  location         Nx01Location? @relation(\"R_Nx04SrItem_locationId\", fields: [locationId], references: [id])\n\n  @@map(\"nx04_sr_item\")\n}\n\n/// =======================================================\n/// Nx05AccountCode — DB table `nx05_account_code`\n/// =======================================================\nmodel Nx05AccountCode {\n  /// [NX05]+[ACCD]+[7碼流水號]，EX : NX05ACCD0000001；啟用最低需求版本：LITE-CORE\n  id                           String       @id @default(dbgenerated(\"gen_nx05_account_code_id()\")) @db.VarChar(15)\n  /// 租戶 ID（外鍵）。；啟用最低需求版本：LITE-CORE\n  tenantId                     String       @map(\"tenant_id\") @db.VarChar(15)\n  /// 科目代碼（唯一），EX：6132=租金/6139=水電費/6150=電話費。；啟用最低需求版本：LITE-CORE\n  code                         String       @db.VarChar(10)\n  /// 科目名稱。；啟用最低需求版本：LITE-CORE\n  name                         String       @db.VarChar(100)\n  /// 科目類別（I=收入/E=支出/A=資產/L=負債）。；啟用最低需求版本：LITE-CORE\n  category                     String       @db.VarChar(1)\n  /// 是否為系統預設科目（TRUE=不可刪除）。；啟用最低需求版本：LITE-CORE\n  isSystem                     Boolean      @default(false) @map(\"is_system\")\n  /// 是否啟用。；啟用最低需求版本：LITE-CORE\n  isActive                     Boolean      @default(true) @map(\"is_active\")\n  /// 備註。；啟用最低需求版本：LITE-CORE\n  remark                       String?      @db.VarChar(200)\n  /// 建立時間。；啟用最低需求版本：LITE-CORE\n  createdAt                    DateTime     @default(now()) @map(\"created_at\")\n  /// 建立人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：LITE-CORE\n  createdBy                    String       @map(\"created_by\") @db.VarChar(15)\n  /// 更新時間。；啟用最低需求版本：LITE-CORE\n  updatedAt                    DateTime     @updatedAt @map(\"updated_at\")\n  /// 更新人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：LITE-CORE\n  updatedBy                    String       @map(\"updated_by\") @db.VarChar(15)\n  tenant                       Nx99Tenant   @relation(\"R_Nx05AccountCode_tenantId\", fields: [tenantId], references: [id])\n  rev_Nx05Paylog_accountCodeId Nx05Paylog[] @relation(\"R_Nx05Paylog_accountCodeId\")\n\n  @@unique([tenantId, code])\n  @@map(\"nx05_account_code\")\n}\n\n/// =======================================================\n/// Nx05Allowance — DB table `nx05_allowance`\n/// =======================================================\nmodel Nx05Allowance {\n  /// [NX05]+[ALOW]+[7碼流水號]，EX : NX05ALOW0000001；啟用最低需求版本：LITE-CORE\n  id                                String              @id @default(dbgenerated(\"gen_nx05_allowance_id()\")) @db.VarChar(15)\n  /// 租戶 ID（外鍵）。；啟用最低需求版本：LITE-CORE\n  tenantId                          String              @map(\"tenant_id\") @db.VarChar(15)\n  /// 折讓單號（唯一），[AL]-[年月]-[機構碼]-[5碼流水號]，EX：AL-202604-HQ0-00001。；啟用最低需求版本：LITE-CORE\n  docNo                             String              @map(\"doc_no\") @db.VarChar(20)\n  /// 折讓方向（P=進貨折讓廠商給我方/S=銷貨折讓我方給客戶）。；啟用最低需求版本：LITE-CORE\n  allowanceType                     String              @map(\"allowance_type\") @db.VarChar(1)\n  /// 交易對象ID（廠商或客戶，FK nx01_partner）。；啟用最低需求版本：LITE-CORE\n  partnerId                         String              @map(\"partner_id\") @db.VarChar(15)\n  /// 折讓日期。；啟用最低需求版本：LITE-CORE\n  allowanceDate                     DateTime            @map(\"allowance_date\") @db.Date\n  /// 關聯應收帳款ID（allowance_type=S時填入，FK nx05_ar_ledger）。；啟用最低需求版本：LITE-CORE\n  refArId                           String?             @map(\"ref_ar_id\") @db.VarChar(15)\n  /// 關聯應付帳款ID（allowance_type=P時填入，FK nx05_ap_ledger）。；啟用最低需求版本：LITE-CORE\n  refApId                           String?             @map(\"ref_ap_id\") @db.VarChar(15)\n  /// 折讓總金額（明細加總）。；啟用最低需求版本：LITE-CORE\n  totalAmount                       Decimal             @default(0) @map(\"total_amount\") @db.Decimal(14, 2)\n  /// 狀態（DRAFT / PENDING / APPROVED / PROCESSED / VOIDED）。；啟用最低需求版本：LITE-CORE\n  status                            String              @default(\"DRAFT\") @db.VarChar(30)\n  /// 核准時間（負責人核准，status=P時填入）。；啟用最低需求版本：LITE-CORE\n  approvedAt                        DateTime?           @map(\"approved_at\")\n  /// 核准人（使用者ID）。；啟用最低需求版本：LITE-CORE\n  approvedBy                        String?             @map(\"approved_by\") @db.VarChar(15)\n  /// 退件原因（負責人退件時必填）。；啟用最低需求版本：LITE-CORE\n  rejectReason                      String?             @map(\"reject_reason\") @db.VarChar(200)\n  /// 備註。；啟用最低需求版本：LITE-CORE\n  remark                            String?             @db.VarChar(200)\n  /// 建立時間。；啟用最低需求版本：LITE-CORE\n  createdAt                         DateTime            @default(now()) @map(\"created_at\")\n  /// 建立人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：LITE-CORE\n  createdBy                         String              @map(\"created_by\") @db.VarChar(15)\n  /// 更新時間。；啟用最低需求版本：LITE-CORE\n  updatedAt                         DateTime            @updatedAt @map(\"updated_at\")\n  /// 更新人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：LITE-CORE\n  updatedBy                         String              @map(\"updated_by\") @db.VarChar(15)\n  tenant                            Nx99Tenant          @relation(\"R_Nx05Allowance_tenantId\", fields: [tenantId], references: [id])\n  partner                           Nx01Partner         @relation(\"R_Nx05Allowance_partnerId\", fields: [partnerId], references: [id])\n  refAr                             Nx05ArLedger?       @relation(\"R_Nx05Allowance_refArId\", fields: [refArId], references: [id])\n  refAp                             Nx05ApLedger?       @relation(\"R_Nx05Allowance_refApId\", fields: [refApId], references: [id])\n  rev_Nx05AllowanceItem_allowanceId Nx05AllowanceItem[] @relation(\"R_Nx05AllowanceItem_allowanceId\")\n\n  @@unique([docNo])\n  @@map(\"nx05_allowance\")\n}\n\n/// =======================================================\n/// Nx05AllowanceItem — DB table `nx05_allowance_item`\n/// =======================================================\nmodel Nx05AllowanceItem {\n  /// [NX05]+[AWIT]+[7碼流水號]，EX : NX05AWIT0000001；啟用最低需求版本：LITE-CORE\n  id             String        @id @default(dbgenerated(\"gen_nx05_allowance_item_id()\")) @db.VarChar(15)\n  /// 對應折讓單表頭ID（FK nx05_allowance）。；啟用最低需求版本：LITE-CORE\n  allowanceId    String        @map(\"allowance_id\") @db.VarChar(15)\n  /// 明細行號（1,2,3…）。；啟用最低需求版本：LITE-CORE\n  lineNo         Int           @default(1) @map(\"line_no\")\n  /// 折讓原因（品質問題/數量短缺/規格不符/定價錯誤/其他）。；啟用最低需求版本：LITE-CORE\n  reason         String        @db.VarChar(200)\n  /// 折讓金額。；啟用最低需求版本：LITE-CORE\n  amount         Decimal       @default(0) @db.Decimal(14, 2)\n  /// 處置方式（O=沖銷AP/AR / D=下次折抵 / R=現金退回）。；啟用最低需求版本：LITE-CORE\n  disposalMethod String        @default(\"O\") @map(\"disposal_method\") @db.VarChar(1)\n  /// 來源單據ID（可空，關聯進貨單RR或銷貨單SO）。；啟用最低需求版本：LITE-CORE\n  refDocId       String?       @map(\"ref_doc_id\") @db.VarChar(15)\n  /// 來源單據類型（RR=進貨單/SO=銷貨單）。；啟用最低需求版本：LITE-CORE\n  refDocType     String?       @map(\"ref_doc_type\") @db.VarChar(2)\n  /// 備註。；啟用最低需求版本：LITE-CORE\n  remark         String?       @db.VarChar(200)\n  /// 建立時間。；啟用最低需求版本：LITE-CORE\n  createdAt      DateTime      @default(now()) @map(\"created_at\")\n  /// 建立人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：LITE-CORE\n  createdBy      String        @map(\"created_by\") @db.VarChar(15)\n  /// 更新時間。；啟用最低需求版本：LITE-CORE\n  updatedAt      DateTime      @updatedAt @map(\"updated_at\")\n  /// 更新人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：LITE-CORE\n  updatedBy      String        @map(\"updated_by\") @db.VarChar(15)\n  allowance      Nx05Allowance @relation(\"R_Nx05AllowanceItem_allowanceId\", fields: [allowanceId], references: [id])\n\n  @@map(\"nx05_allowance_item\")\n}\n\n/// =======================================================\n/// Nx05ApLedger — DB table `nx05_ap_ledger`\n/// =======================================================\nmodel Nx05ApLedger {\n  /// [NX05]+[APLE]+[7碼流水號]，EX : NX05APLE0000001；啟用最低需求版本：LITE-CORE\n  id                        String          @id @default(dbgenerated(\"gen_nx05_ap_ledger_id()\")) @db.VarChar(15)\n  /// 租戶 ID（外鍵）。；啟用最低需求版本：LITE-CORE\n  tenantId                  String          @map(\"tenant_id\") @db.VarChar(15)\n  /// 應付帳款單號（唯一），[AP]-[年月]-[機構碼]-[5碼流水號]，EX：AP-202604-HQ0-00001。；啟用最低需求版本：LITE-CORE\n  docNo                     String          @map(\"doc_no\") @db.VarChar(20)\n  /// 來源類型（PO=採購單/RR=進貨單/TI=調貨單）。PLUS前PO確認產生；LITE進貨入帳後產生。；啟用最低需求版本：LITE-CORE\n  sourceType                String          @default(\"PO\") @map(\"source_type\") @db.VarChar(2)\n  /// 來源採購單ID（可空，PLUS限定，FK nx02_po）。；啟用最低需求版本：LITE-CORE\n  poId                      String?         @map(\"po_id\") @db.VarChar(15)\n  /// 來源進貨單ID（可空，LITE直接由RR產生，FK nx02_rr）。；啟用最低需求版本：LITE-CORE\n  rrId                      String?         @map(\"rr_id\") @db.VarChar(15)\n  /// 來源調貨單ID（可空，FK nx02_ti）。；啟用最低需求版本：LITE-CORE\n  tiId                      String?         @map(\"ti_id\") @db.VarChar(15)\n  /// 廠商ID（FK nx01_partner）。；啟用最低需求版本：LITE-CORE\n  supplierId                String          @map(\"supplier_id\") @db.VarChar(15)\n  /// 應付帳款產生日期。；啟用最低需求版本：LITE-CORE\n  apDate                    DateTime        @map(\"ap_date\") @db.Date\n  /// 到期日（依付款條件計算）。；啟用最低需求版本：LITE-CORE\n  dueDate                   DateTime        @map(\"due_date\") @db.Date\n  /// 幣別ID（FK nx01_currency）。；啟用最低需求版本：LITE-CORE\n  currencyId                String          @default(\"TWD\") @map(\"currency_id\") @db.VarChar(15)\n  /// 應付金額（含稅）。；啟用最低需求版本：LITE-CORE\n  originalAmount            Decimal         @default(0) @map(\"original_amount\") @db.Decimal(14, 2)\n  /// 已付金額（累計）。；啟用最低需求版本：LITE-CORE\n  paidAmount                Decimal         @default(0) @map(\"paid_amount\") @db.Decimal(14, 2)\n  /// 未付餘額（original_amount - paid_amount）。；啟用最低需求版本：LITE-CORE\n  balanceAmount             Decimal         @default(0) @map(\"balance_amount\") @db.Decimal(14, 2)\n  /// 狀態（OPEN / PARTIAL / PAID / OVERDUE / VOID）。；啟用最低需求版本：LITE-CORE\n  status                    String          @default(\"OPEN\") @db.VarChar(30)\n  /// 付款條件快照（自廠商主檔帶入）。；啟用最低需求版本：LITE-CORE\n  paymentTerm               String          @default(\"NET30\") @map(\"payment_term\") @db.VarChar(20)\n  /// 核銷時間（status=C時填入）。；啟用最低需求版本：LITE-CORE\n  writeOffAt                DateTime?       @map(\"write_off_at\")\n  /// 核銷人（使用者ID）。；啟用最低需求版本：LITE-CORE\n  writeOffBy                String?         @map(\"write_off_by\") @db.VarChar(15)\n  /// 備註。；啟用最低需求版本：LITE-CORE\n  remark                    String?         @db.VarChar(200)\n  /// 建立時間。；啟用最低需求版本：LITE-CORE\n  createdAt                 DateTime        @default(now()) @map(\"created_at\")\n  /// 建立人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：LITE-CORE\n  createdBy                 String          @map(\"created_by\") @db.VarChar(15)\n  /// 更新時間。；啟用最低需求版本：LITE-CORE\n  updatedAt                 DateTime        @updatedAt @map(\"updated_at\")\n  /// 更新人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：LITE-CORE\n  updatedBy                 String          @map(\"updated_by\") @db.VarChar(15)\n  tenant                    Nx99Tenant      @relation(\"R_Nx05ApLedger_tenantId\", fields: [tenantId], references: [id])\n  po                        Nx02Po?         @relation(\"R_Nx05ApLedger_poId\", fields: [poId], references: [id])\n  rr                        Nx02Rr?         @relation(\"R_Nx05ApLedger_rrId\", fields: [rrId], references: [id])\n  ti                        Nx02Ti?         @relation(\"R_Nx05ApLedger_tiId\", fields: [tiId], references: [id])\n  supplier                  Nx01Partner     @relation(\"R_Nx05ApLedger_supplierId\", fields: [supplierId], references: [id])\n  currency                  Nx01Currency    @relation(\"R_Nx05ApLedger_currencyId\", fields: [currencyId], references: [id])\n  rev_Nx05Allowance_refApId Nx05Allowance[] @relation(\"R_Nx05Allowance_refApId\")\n  rev_Nx05Paylog_apId       Nx05Paylog[]    @relation(\"R_Nx05Paylog_apId\")\n\n  @@unique([docNo])\n  @@map(\"nx05_ap_ledger\")\n}\n\n/// =======================================================\n/// Nx05ArLedger — DB table `nx05_ar_ledger`\n/// =======================================================\nmodel Nx05ArLedger {\n  /// [NX05]+[ARLE]+[7碼流水號]，EX : NX05ARLE0000001；啟用最低需求版本：LITE-CORE\n  id                        String          @id @default(dbgenerated(\"gen_nx05_ar_ledger_id()\")) @db.VarChar(15)\n  /// 租戶 ID（外鍵）。；啟用最低需求版本：LITE-CORE\n  tenantId                  String          @map(\"tenant_id\") @db.VarChar(15)\n  /// 應收帳款單號（唯一），[AR]-[年月]-[機構碼]-[5碼流水號]，EX：AR-202604-HQ0-00001。；啟用最低需求版本：LITE-CORE\n  docNo                     String          @map(\"doc_no\") @db.VarChar(20)\n  /// 來源銷貨單ID（FK nx04_so）。；啟用最低需求版本：LITE-CORE\n  soId                      String          @map(\"so_id\") @db.VarChar(15)\n  /// 客戶ID（快照自SO，FK nx01_partner）。；啟用最低需求版本：LITE-CORE\n  customerId                String          @map(\"customer_id\") @db.VarChar(15)\n  /// 應收帳款產生日期。；啟用最低需求版本：LITE-CORE\n  arDate                    DateTime        @map(\"ar_date\") @db.Date\n  /// 到期日（依付款條件計算）。；啟用最低需求版本：LITE-CORE\n  dueDate                   DateTime        @map(\"due_date\") @db.Date\n  /// 幣別ID（FK nx01_currency）。；啟用最低需求版本：LITE-CORE\n  currencyId                String          @default(\"TWD\") @map(\"currency_id\") @db.VarChar(15)\n  /// 應收金額（含稅）。；啟用最低需求版本：LITE-CORE\n  originalAmount            Decimal         @default(0) @map(\"original_amount\") @db.Decimal(14, 2)\n  /// 已收金額（累計）。；啟用最低需求版本：LITE-CORE\n  paidAmount                Decimal         @default(0) @map(\"paid_amount\") @db.Decimal(14, 2)\n  /// 未收餘額（original_amount - paid_amount）。；啟用最低需求版本：LITE-CORE\n  balanceAmount             Decimal         @default(0) @map(\"balance_amount\") @db.Decimal(14, 2)\n  /// 狀態（OPEN / PARTIAL / PAID / OVERDUE / WRITTEN_OFF）。；啟用最低需求版本：LITE-CORE\n  status                    String          @default(\"OPEN\") @db.VarChar(30)\n  /// 付款條件快照（自SO帶入）。；啟用最低需求版本：LITE-CORE\n  paymentTerm               String          @default(\"NET30\") @map(\"payment_term\") @db.VarChar(20)\n  /// 逾期天數（系統每日計算，due_date < today 時累計）。；啟用最低需求版本：LITE-CORE\n  overdueDays               Int             @default(0) @map(\"overdue_days\")\n  /// 部分收款是否已獲負責人核准（partial payment 需核准）。；啟用最低需求版本：LITE-CORE\n  isPartialApproved         Boolean         @default(false) @map(\"is_partial_approved\")\n  /// 核銷時間（status=C時填入）。；啟用最低需求版本：LITE-CORE\n  writeOffAt                DateTime?       @map(\"write_off_at\")\n  /// 核銷人（使用者ID）。；啟用最低需求版本：LITE-CORE\n  writeOffBy                String?         @map(\"write_off_by\") @db.VarChar(15)\n  /// 備註。；啟用最低需求版本：LITE-CORE\n  remark                    String?         @db.VarChar(200)\n  /// 建立時間。；啟用最低需求版本：LITE-CORE\n  createdAt                 DateTime        @default(now()) @map(\"created_at\")\n  /// 建立人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：LITE-CORE\n  createdBy                 String          @map(\"created_by\") @db.VarChar(15)\n  /// 更新時間。；啟用最低需求版本：LITE-CORE\n  updatedAt                 DateTime        @updatedAt @map(\"updated_at\")\n  /// 更新人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：LITE-CORE\n  updatedBy                 String          @map(\"updated_by\") @db.VarChar(15)\n  tenant                    Nx99Tenant      @relation(\"R_Nx05ArLedger_tenantId\", fields: [tenantId], references: [id])\n  so                        Nx04So          @relation(\"R_Nx05ArLedger_soId\", fields: [soId], references: [id])\n  customer                  Nx01Partner     @relation(\"R_Nx05ArLedger_customerId\", fields: [customerId], references: [id])\n  currency                  Nx01Currency    @relation(\"R_Nx05ArLedger_currencyId\", fields: [currencyId], references: [id])\n  rev_Nx05Allowance_refArId Nx05Allowance[] @relation(\"R_Nx05Allowance_refArId\")\n  rev_Nx05Paylog_arId       Nx05Paylog[]    @relation(\"R_Nx05Paylog_arId\")\n\n  @@unique([docNo])\n  @@map(\"nx05_ar_ledger\")\n}\n\n/// =======================================================\n/// Nx05Closing — DB table `nx05_closing`\n/// =======================================================\nmodel Nx05Closing {\n  /// [NX05]+[CLOS]+[7碼流水號]，EX : NX05CLOS0000001；啟用最低需求版本：LITE-CORE\n  id              String     @id @default(dbgenerated(\"gen_nx05_closing_id()\")) @db.VarChar(15)\n  /// 租戶 ID（外鍵）。；啟用最低需求版本：LITE-CORE\n  tenantId        String     @map(\"tenant_id\") @db.VarChar(15)\n  /// 關帳單號（唯一），[CL]-[年月]-[機構碼]-[5碼流水號]，EX：CL-202604-HQ0-00001。；啟用最低需求版本：LITE-CORE\n  docNo           String     @map(\"doc_no\") @db.VarChar(20)\n  /// 關帳日期（每日一筆，唯一）。；啟用最低需求版本：LITE-CORE\n  closingDate     DateTime   @map(\"closing_date\") @db.Date\n  /// 關帳時間（人工執行或系統自動）。；啟用最低需求版本：LITE-CORE\n  closedAt        DateTime?  @map(\"closed_at\")\n  /// 關帳執行人（使用者ID）。；啟用最低需求版本：LITE-CORE\n  closedBy        String?    @map(\"closed_by\") @db.VarChar(15)\n  /// 是否為系統自動關帳（TRUE=系統自動/FALSE=人工執行）。；啟用最低需求版本：LITE-CORE\n  isAuto          Boolean    @default(false) @map(\"is_auto\")\n  /// 401報表列印/下載時間。；啟用最低需求版本：LITE-CORE\n  reportPrintedAt DateTime?  @map(\"report_printed_at\")\n  /// 報表列印人（使用者ID）。；啟用最低需求版本：LITE-CORE\n  reportPrintedBy String?    @map(\"report_printed_by\") @db.VarChar(15)\n  /// 狀態（OPEN / CLOSING / CLOSED / REOPENED）。；啟用最低需求版本：LITE-CORE\n  status          String     @default(\"OPEN\") @db.VarChar(30)\n  /// 解除關帳時間（status=R時填入）。；啟用最低需求版本：LITE-CORE\n  reopenedAt      DateTime?  @map(\"reopened_at\")\n  /// 解除關帳人（負責人，使用者ID）。；啟用最低需求版本：LITE-CORE\n  reopenedBy      String?    @map(\"reopened_by\") @db.VarChar(15)\n  /// 解除原因（必填，永久保存作稽核依據）。；啟用最低需求版本：LITE-CORE\n  reopenReason    String?    @map(\"reopen_reason\") @db.VarChar(200)\n  /// 備註。；啟用最低需求版本：LITE-CORE\n  remark          String?    @db.VarChar(200)\n  /// 建立時間。；啟用最低需求版本：LITE-CORE\n  createdAt       DateTime   @default(now()) @map(\"created_at\")\n  /// 建立人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：LITE-CORE\n  createdBy       String     @map(\"created_by\") @db.VarChar(15)\n  /// 更新時間。；啟用最低需求版本：LITE-CORE\n  updatedAt       DateTime   @updatedAt @map(\"updated_at\")\n  /// 更新人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：LITE-CORE\n  updatedBy       String     @map(\"updated_by\") @db.VarChar(15)\n  tenant          Nx99Tenant @relation(\"R_Nx05Closing_tenantId\", fields: [tenantId], references: [id])\n\n  @@map(\"nx05_closing\")\n}\n\n/// =======================================================\n/// Nx05Note — DB table `nx05_note`\n/// =======================================================\nmodel Nx05Note {\n  /// [NX05]+[NOTE]+[7碼流水號]，EX : NX05NOTE0000001；啟用最低需求版本：LITE-CORE\n  id                    String       @id @default(dbgenerated(\"gen_nx05_note_id()\")) @db.VarChar(15)\n  /// 租戶 ID（外鍵）。；啟用最低需求版本：LITE-CORE\n  tenantId              String       @map(\"tenant_id\") @db.VarChar(15)\n  /// 票據系統單號（唯一），[NT]-[年月]-[機構碼]-[5碼流水號]，EX：NT-202604-HQ0-00001。票號本身另欄填入。；啟用最低需求版本：LITE-CORE\n  docNo                 String       @map(\"doc_no\") @db.VarChar(20)\n  /// 票據類型（CK=支票/PN=本票）。；啟用最低需求版本：LITE-CORE\n  noteType              String       @map(\"note_type\") @db.VarChar(2)\n  /// 方向（R=應收票據/P=應付票據）。；啟用最低需求版本：LITE-CORE\n  direction             String       @db.VarChar(1)\n  /// 票據來源/受款人（FK nx01_partner）。；啟用最低需求版本：LITE-CORE\n  partnerId             String       @map(\"partner_id\") @db.VarChar(15)\n  /// 票號（銀行票據編號，人工填入）。；啟用最低需求版本：LITE-CORE\n  noteNo                String       @map(\"note_no\") @db.VarChar(50)\n  /// 銀行名稱。；啟用最低需求版本：LITE-CORE\n  bankName              String       @map(\"bank_name\") @db.VarChar(100)\n  /// 帳號末四碼（選填，供對帳使用）。；啟用最低需求版本：LITE-CORE\n  bankAccount           String?      @map(\"bank_account\") @db.VarChar(30)\n  /// 票面金額。；啟用最低需求版本：LITE-CORE\n  amount                Decimal      @default(0) @db.Decimal(14, 2)\n  /// 幣別ID（FK nx01_currency）。；啟用最低需求版本：LITE-CORE\n  currencyId            String       @default(\"TWD\") @map(\"currency_id\") @db.VarChar(10)\n  /// 開票日期。；啟用最低需求版本：LITE-CORE\n  issueDate             DateTime     @map(\"issue_date\") @db.Date\n  /// 到期日。；啟用最低需求版本：LITE-CORE\n  dueDate               DateTime     @map(\"due_date\") @db.Date\n  /// 狀態（DRAFT / ACTIVE / CLEARED / BOUNCED / VOIDED）。；啟用最低需求版本：LITE-CORE\n  status                String       @default(\"DRAFT\") @db.VarChar(30)\n  /// 兌現時間（status=C時填入）。；啟用最低需求版本：LITE-CORE\n  clearedAt             DateTime?    @map(\"cleared_at\")\n  /// 退票時間（status=B時填入）。；啟用最低需求版本：LITE-CORE\n  bouncedAt             DateTime?    @map(\"bounced_at\")\n  /// 退票原因（status=B時必填）。；啟用最低需求版本：LITE-CORE\n  bouncedReason         String?      @map(\"bounced_reason\") @db.VarChar(200)\n  /// 關聯收付款紀錄ID（票據開立時關聯，FK nx05_paylog）。；啟用最低需求版本：LITE-CORE\n  paylogId              String?      @map(\"paylog_id\") @db.VarChar(15)\n  /// 備註。；啟用最低需求版本：LITE-CORE\n  remark                String?      @db.VarChar(200)\n  /// 建立時間。；啟用最低需求版本：LITE-CORE\n  createdAt             DateTime     @default(now()) @map(\"created_at\")\n  /// 建立人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：LITE-CORE\n  createdBy             String       @map(\"created_by\") @db.VarChar(15)\n  /// 更新時間。；啟用最低需求版本：LITE-CORE\n  updatedAt             DateTime     @updatedAt @map(\"updated_at\")\n  /// 更新人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：LITE-CORE\n  updatedBy             String       @map(\"updated_by\") @db.VarChar(15)\n  tenant                Nx99Tenant   @relation(\"R_Nx05Note_tenantId\", fields: [tenantId], references: [id])\n  partner               Nx01Partner  @relation(\"R_Nx05Note_partnerId\", fields: [partnerId], references: [id])\n  currency              Nx01Currency @relation(\"R_Nx05Note_currencyId\", fields: [currencyId], references: [id])\n  paylog                Nx05Paylog?  @relation(\"R_Nx05Note_paylogId\", fields: [paylogId], references: [id])\n  rev_Nx05Paylog_noteId Nx05Paylog[] @relation(\"R_Nx05Paylog_noteId\")\n\n  @@unique([docNo])\n  @@map(\"nx05_note\")\n}\n\n/// =======================================================\n/// Nx05Paylog — DB table `nx05_paylog`\n/// =======================================================\nmodel Nx05Paylog {\n  /// [NX05]+[PAYL]+[7碼流水號]，EX : NX05PAYL0000001；啟用最低需求版本：LITE-CORE\n  id                    String           @id @default(dbgenerated(\"gen_nx05_paylog_id()\")) @db.VarChar(15)\n  /// 租戶 ID（外鍵）。；啟用最低需求版本：LITE-CORE\n  tenantId              String           @map(\"tenant_id\") @db.VarChar(15)\n  /// 收付款單號（唯一），[PY]-[年月]-[機構碼]-[5碼流水號]，EX：PY-202604-HQ0-00001。；啟用最低需求版本：LITE-CORE\n  docNo                 String           @map(\"doc_no\") @db.VarChar(20)\n  /// 收付款類型（CR=客戶收款/CP=廠商付款/RR=廠商退款/RC=客戶退款/EX=費用支出）。；啟用最低需求版本：LITE-CORE\n  payType               String           @map(\"pay_type\") @db.VarChar(2)\n  /// 收付款日期。；啟用最低需求版本：LITE-CORE\n  payDate               DateTime         @map(\"pay_date\") @db.Date\n  /// 交易對象ID（EX費用支出可空，FK nx01_partner）。；啟用最低需求版本：LITE-CORE\n  partnerId             String?          @map(\"partner_id\") @db.VarChar(15)\n  /// 關聯應收帳款ID（pay_type=CR/RC時填入，FK nx05_ar_ledger）。；啟用最低需求版本：LITE-CORE\n  arId                  String?          @map(\"ar_id\") @db.VarChar(15)\n  /// 關聯應付帳款ID（pay_type=CP/RR時填入，FK nx05_ap_ledger）。；啟用最低需求版本：LITE-CORE\n  apId                  String?          @map(\"ap_id\") @db.VarChar(15)\n  /// 收付款金額（正數）。；啟用最低需求版本：LITE-CORE\n  amount                Decimal          @default(0) @db.Decimal(14, 2)\n  /// 幣別ID（FK nx01_currency）。；啟用最低需求版本：LITE-CORE\n  currencyId            String           @default(\"TWD\") @map(\"currency_id\") @db.VarChar(15)\n  /// 付款方式（CA=現金/TT=匯款/CK=支票/PN=本票）。；啟用最低需求版本：LITE-CORE\n  payMethod             String           @default(\"CA\") @map(\"pay_method\") @db.VarChar(2)\n  /// 關聯票據ID（pay_method=CK/PN時填入，FK nx05_note）。；啟用最低需求版本：LITE-CORE\n  noteId                String?          @map(\"note_id\") @db.VarChar(15)\n  /// 會計科目ID（pay_type=EX費用支出時必填，FK nx05_account_code）。；啟用最低需求版本：LITE-CORE\n  accountCodeId         String?          @map(\"account_code_id\") @db.VarChar(15)\n  /// 現金餘額快照（pay_method=CA時，交易後的現金庫存餘額）。；啟用最低需求版本：LITE-CORE\n  cashBalanceAfter      Decimal?         @map(\"cash_balance_after\") @db.Decimal(14, 2)\n  /// 單據狀態（DRAFT / POSTED / VOIDED）。；啟用最低需求版本：LITE-CORE\n  status                String           @default(\"DRAFT\") @map(\"status\") @db.VarChar(20)\n  /// 作廢時間。；啟用最低需求版本：LITE-CORE\n  voidedAt              DateTime?        @map(\"voided_at\")\n  /// 過帳時間（POSTED 時填入）。；啟用最低需求版本：LITE-CORE\n  postedAt              DateTime?        @map(\"posted_at\")\n  /// 備註。；啟用最低需求版本：LITE-CORE\n  remark                String?          @db.VarChar(200)\n  /// 建立時間。；啟用最低需求版本：LITE-CORE\n  createdAt             DateTime         @default(now()) @map(\"created_at\")\n  /// 建立人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：LITE-CORE\n  createdBy             String           @map(\"created_by\") @db.VarChar(15)\n  /// 更新時間。；啟用最低需求版本：LITE-CORE\n  updatedAt             DateTime         @updatedAt @map(\"updated_at\")\n  /// 更新人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：LITE-CORE\n  updatedBy             String           @map(\"updated_by\") @db.VarChar(15)\n  tenant                Nx99Tenant       @relation(\"R_Nx05Paylog_tenantId\", fields: [tenantId], references: [id])\n  partner               Nx01Partner?     @relation(\"R_Nx05Paylog_partnerId\", fields: [partnerId], references: [id])\n  ar                    Nx05ArLedger?    @relation(\"R_Nx05Paylog_arId\", fields: [arId], references: [id])\n  ap                    Nx05ApLedger?    @relation(\"R_Nx05Paylog_apId\", fields: [apId], references: [id])\n  currency              Nx01Currency     @relation(\"R_Nx05Paylog_currencyId\", fields: [currencyId], references: [id])\n  note                  Nx05Note?        @relation(\"R_Nx05Paylog_noteId\", fields: [noteId], references: [id])\n  accountCode           Nx05AccountCode? @relation(\"R_Nx05Paylog_accountCodeId\", fields: [accountCodeId], references: [id])\n  rev_Nx05Note_paylogId Nx05Note[]       @relation(\"R_Nx05Note_paylogId\")\n\n  @@unique([docNo])\n  @@map(\"nx05_paylog\")\n}\n\n/// =======================================================\n/// Nx06Dn — DB table `nx06_dn`\n/// =======================================================\nmodel Nx06Dn {\n  /// [NX06]+[DNHD]+[7碼流水號]，EX : NX06DNHD0000001；啟用最低需求版本：LITE-CORE\n  id                   String        @id @default(dbgenerated(\"gen_nx06_dn_id()\")) @db.VarChar(15)\n  /// 租戶 ID（外鍵）。；啟用最低需求版本：LITE-CORE\n  tenantId             String        @map(\"tenant_id\") @db.VarChar(15)\n  /// 出發倉庫ID（FK nx01_warehouse）。；啟用最低需求版本：LITE-CORE\n  warehouseId          String        @map(\"warehouse_id\") @db.VarChar(15)\n  /// 送貨單號（唯一），[DN]+[年月]+[倉別]+[5碼流水號]，EX：DN-202604-Z01-00001；啟用最低需求版本：LITE-CORE\n  docNo                String        @map(\"doc_no\") @db.VarChar(30)\n  /// 送貨日期。；啟用最低需求版本：LITE-CORE\n  dnDate               DateTime      @map(\"dn_date\") @db.Date\n  /// 外務人員ID（FK nx01_user）。；啟用最低需求版本：LITE-CORE\n  driverUserId         String        @map(\"driver_user_id\") @db.VarChar(15)\n  /// 車牌號碼（選填）。；啟用最低需求版本：LITE-CORE\n  vehicleNo            String?       @map(\"vehicle_no\") @db.VarChar(20)\n  /// 物流類別（DELIVERY / PICKUP / INTL_SHIPPING / RETURN_PICKUP）。；啟用最低需求版本：LITE-CORE\n  logisticsType        String        @default(\"DELIVERY\") @map(\"logistics_type\") @db.VarChar(30)\n  /// 狀態（DRAFT / DISPATCHED / DELIVERED / PICKED_UP / FAILED / VOIDED；國際另含 CUSTOMS / IN_TRANSIT）。；啟用最低需求版本：LITE-CORE\n  status               String        @default(\"DRAFT\") @db.VarChar(30)\n  /// 最近一次 GPS 緯度（外務 /driver）。；啟用最低需求版本：LITE-CORE\n  lastLat              Decimal?      @map(\"last_lat\") @db.Decimal(12, 8)\n  /// 最近一次 GPS 經度。；啟用最低需求版本：LITE-CORE\n  lastLng              Decimal?      @map(\"last_lng\") @db.Decimal(12, 8)\n  /// GPS 更新時間。；啟用最低需求版本：LITE-CORE\n  lastLocationAt       DateTime?     @map(\"last_location_at\")\n  /// 報關單號（國際物流）。；啟用最低需求版本：LITE-CORE\n  customsDeclarationNo String?       @map(\"customs_declaration_no\") @db.VarChar(80)\n  /// 起運港。；啟用最低需求版本：LITE-CORE\n  originPort           String?       @map(\"origin_port\") @db.VarChar(100)\n  /// 目的港。；啟用最低需求版本：LITE-CORE\n  destinationPort      String?       @map(\"destination_port\") @db.VarChar(100)\n  /// 預計到港日。；啟用最低需求版本：LITE-CORE\n  etaDate              DateTime?     @map(\"eta_date\") @db.Date\n  /// 來源銷貨單（配送單自動產生時填入）。；啟用最低需求版本：LITE-CORE\n  sourceSoId           String?       @map(\"source_so_id\") @db.VarChar(15)\n  /// 來源銷退單（退貨取件單）。；啟用最低需求版本：LITE-CORE\n  sourceSrId           String?       @map(\"source_sr_id\") @db.VarChar(15)\n  /// 出發時間（外務點擊出發後記錄）。；啟用最低需求版本：LITE-CORE\n  departedAt           DateTime?     @map(\"departed_at\")\n  /// 全部任務完成時間。；啟用最低需求版本：LITE-CORE\n  completedAt          DateTime?     @map(\"completed_at\")\n  /// 備註（含臨時收件等口頭回報記錄）。；啟用最低需求版本：LITE-CORE\n  remark               String?       @db.VarChar(200)\n  /// 建立時間。；啟用最低需求版本：LITE-CORE\n  createdAt            DateTime      @default(now()) @map(\"created_at\")\n  /// 建立人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：LITE-CORE\n  createdBy            String        @map(\"created_by\") @db.VarChar(15)\n  /// 更新時間。；啟用最低需求版本：LITE-CORE\n  updatedAt            DateTime      @updatedAt @map(\"updated_at\")\n  /// 更新人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：LITE-CORE\n  updatedBy            String        @map(\"updated_by\") @db.VarChar(15)\n  tenant               Nx99Tenant    @relation(\"R_Nx06Dn_tenantId\", fields: [tenantId], references: [id])\n  warehouse            Nx01Warehouse @relation(\"R_Nx06Dn_warehouseId\", fields: [warehouseId], references: [id])\n  driverUser           Nx01User      @relation(\"R_Nx06Dn_driverUserId\", fields: [driverUserId], references: [id])\n  sourceSo             Nx04So?       @relation(\"R_Nx06Dn_sourceSoId\", fields: [sourceSoId], references: [id])\n  sourceSr             Nx04Sr?       @relation(\"R_Nx06Dn_sourceSrId\", fields: [sourceSrId], references: [id])\n  rev_Nx06DnItem_dnId  Nx06DnItem[]  @relation(\"R_Nx06DnItem_dnId\")\n  rev_Nx06DnStop_dnId  Nx06DnStop[]  @relation(\"R_Nx06DnStop_dnId\")\n\n  @@unique([docNo])\n  @@index([tenantId, sourceSoId], map: \"nx06_dn_source_so_idx\")\n  @@index([tenantId, sourceSrId], map: \"nx06_dn_source_sr_idx\")\n  @@index([tenantId, logisticsType], map: \"nx06_dn_tenant_logistics_idx\")\n  @@map(\"nx06_dn\")\n}\n\n/// =======================================================\n/// Nx06DnItem — DB table `nx06_dn_item`\n/// =======================================================\nmodel Nx06DnItem {\n  /// [NX06]+[DNIT]+[7碼流水號]，EX : NX06DNIT0000001；啟用最低需求版本：LITE-CORE\n  id              String      @id @default(dbgenerated(\"gen_nx06_dn_item_id()\")) @db.VarChar(15)\n  /// 對應送貨單表頭ID（FK nx06_dn）。；啟用最低需求版本：LITE-CORE\n  dnId            String      @map(\"dn_id\") @db.VarChar(15)\n  /// 對應停靠點ID（FK nx06_dn_stop）。；啟用最低需求版本：LITE-CORE\n  stopId          String      @map(\"stop_id\") @db.VarChar(15)\n  /// 明細行號（1,2,3…）。；啟用最低需求版本：LITE-CORE\n  lineNo          Int         @map(\"line_no\")\n  /// 來源單據類型（SO=銷貨單NX04/ST=調撥單NX03/TI=調貨單NX02/PR=退供應商NX02/SR=銷退單NX04）。；啟用最低需求版本：LITE-CORE\n  sourceDocType   String      @map(\"source_doc_type\") @db.VarChar(2)\n  /// 來源單據ID。；啟用最低需求版本：LITE-CORE\n  sourceDocId     String      @map(\"source_doc_id\") @db.VarChar(15)\n  /// 來源明細ID（可空）。；啟用最低需求版本：LITE-CORE\n  sourceItemId    String?     @map(\"source_item_id\") @db.VarChar(15)\n  /// 關聯包裹ID（調撥/寄貨有包貨時填入，FK nx03_parcel）。；啟用最低需求版本：LITE-CORE\n  parcelId        String?     @map(\"parcel_id\") @db.VarChar(15)\n  /// 零件ID（FK nx01_part，PICKUP/RETURN任務時填入）。；啟用最低需求版本：LITE-CORE\n  partId          String?     @map(\"part_id\") @db.VarChar(15)\n  /// 零件料號快照。；啟用最低需求版本：LITE-CORE\n  partNo          String?     @map(\"part_no\") @db.VarChar(50)\n  /// 零件名稱快照。；啟用最低需求版本：LITE-CORE\n  partName        String?     @map(\"part_name\") @db.VarChar(200)\n  /// 應送/取數量。；啟用最低需求版本：LITE-CORE\n  qty             Decimal     @default(0) @db.Decimal(14, 4)\n  /// 交付狀態（P=待確認/C=正常交付/E=異常）。外務可標記異常，客戶確認後再簽名。；啟用最低需求版本：LITE-CORE\n  deliveryStatus  String      @default(\"P\") @map(\"delivery_status\") @db.VarChar(1)\n  /// 異常類型（W=送錯料號/Q=數量不符/D=貨物損壞/O=其他）。delivery_status=E時必填。；啟用最低需求版本：LITE-CORE\n  exceptionType   String?     @map(\"exception_type\") @db.VarChar(1)\n  /// 異常說明（delivery_status=E時必填）。；啟用最低需求版本：LITE-CORE\n  exceptionReason String?     @map(\"exception_reason\") @db.VarChar(200)\n  /// 備註。；啟用最低需求版本：LITE-CORE\n  remark          String?     @db.VarChar(200)\n  /// 建立時間。；啟用最低需求版本：LITE-CORE\n  createdAt       DateTime    @default(now()) @map(\"created_at\")\n  /// 更新時間。；啟用最低需求版本：LITE-CORE\n  updatedAt       DateTime    @updatedAt @map(\"updated_at\")\n  /// 更新人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：LITE-CORE\n  updatedBy       String      @map(\"updated_by\") @db.VarChar(15)\n  dn              Nx06Dn      @relation(\"R_Nx06DnItem_dnId\", fields: [dnId], references: [id])\n  stop            Nx06DnStop  @relation(\"R_Nx06DnItem_stopId\", fields: [stopId], references: [id])\n  parcel          Nx03Parcel? @relation(\"R_Nx06DnItem_parcelId\", fields: [parcelId], references: [id])\n  part            Nx01Part?   @relation(\"R_Nx06DnItem_partId\", fields: [partId], references: [id])\n\n  @@map(\"nx06_dn_item\")\n}\n\n/// =======================================================\n/// Nx06DnStop — DB table `nx06_dn_stop`\n/// =======================================================\nmodel Nx06DnStop {\n  /// [NX06]+[DNST]+[7碼流水號]，EX : NX06DNST0000001；啟用最低需求版本：LITE-CORE\n  id                    String         @id @default(dbgenerated(\"gen_nx06_dn_stop_id()\")) @db.VarChar(15)\n  /// 對應送貨單表頭ID（FK nx06_dn）。；啟用最低需求版本：LITE-CORE\n  dnId                  String         @map(\"dn_id\") @db.VarChar(15)\n  /// 停靠順序號碼（1,2,3…），物流組長安排路線順序。；啟用最低需求版本：LITE-CORE\n  stopNo                Int            @map(\"stop_no\")\n  /// 任務類型（D=DELIVER送貨/K=PICKUP取貨/R=RETURN退貨/C=COLLECT取回退貨）。；啟用最低需求版本：LITE-CORE\n  taskType              String         @map(\"task_type\") @db.VarChar(1)\n  /// 交易對象ID（客戶或同行，FK nx01_partner）。；啟用最低需求版本：LITE-CORE\n  partnerId             String?        @map(\"partner_id\") @db.VarChar(15)\n  /// 目標倉庫ID（調撥送貨時填入，FK nx01_warehouse）。；啟用最低需求版本：LITE-CORE\n  warehouseId           String?        @map(\"warehouse_id\") @db.VarChar(15)\n  /// 停靠地址。；啟用最低需求版本：LITE-CORE\n  address               String         @db.VarChar(200)\n  /// 聯絡人姓名（選填）。；啟用最低需求版本：LITE-CORE\n  contactName           String?        @map(\"contact_name\") @db.VarChar(50)\n  /// 聯絡電話（選填）。；啟用最低需求版本：LITE-CORE\n  contactPhone          String?        @map(\"contact_phone\") @db.VarChar(30)\n  /// 停靠狀態（P=待到達/D=已到達/C=已完成/E=異常）。；啟用最低需求版本：LITE-CORE\n  status                String         @default(\"P\") @db.VarChar(1)\n  /// 實際到達時間。；啟用最低需求版本：LITE-CORE\n  arrivedAt             DateTime?      @map(\"arrived_at\")\n  /// 此停靠點完成時間。；啟用最低需求版本：LITE-CORE\n  completedAt           DateTime?      @map(\"completed_at\")\n  /// 簽收方式（C=客戶簽收/W=倉管簽收/N=不需簽收）。；啟用最低需求版本：LITE-CORE\n  signerType            String         @default(\"N\") @map(\"signer_type\") @db.VarChar(1)\n  /// 簽收時間（signer_type=C/W時填入）。；啟用最低需求版本：LITE-CORE\n  signedAt              DateTime?      @map(\"signed_at\")\n  /// 簽收人姓名（客戶或倉管）。；啟用最低需求版本：LITE-CORE\n  signedByName          String?        @map(\"signed_by_name\") @db.VarChar(50)\n  /// 電子簽名照片路徑（簽名後上傳存儲）。；啟用最低需求版本：LITE-CORE\n  signatureUrl          String?        @map(\"signature_url\") @db.VarChar(500)\n  /// 停靠點異常說明（status=E時填入，例：客戶不在/地址錯誤）。；啟用最低需求版本：LITE-CORE\n  exceptionRemark       String?        @map(\"exception_remark\") @db.VarChar(200)\n  /// 備註。；啟用最低需求版本：LITE-CORE\n  remark                String?        @db.VarChar(200)\n  /// 建立時間。；啟用最低需求版本：LITE-CORE\n  createdAt             DateTime       @default(now()) @map(\"created_at\")\n  /// 更新時間。；啟用最低需求版本：LITE-CORE\n  updatedAt             DateTime       @updatedAt @map(\"updated_at\")\n  /// 更新人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：LITE-CORE\n  updatedBy             String         @map(\"updated_by\") @db.VarChar(15)\n  dn                    Nx06Dn         @relation(\"R_Nx06DnStop_dnId\", fields: [dnId], references: [id])\n  partner               Nx01Partner?   @relation(\"R_Nx06DnStop_partnerId\", fields: [partnerId], references: [id])\n  warehouse             Nx01Warehouse? @relation(\"R_Nx06DnStop_warehouseId\", fields: [warehouseId], references: [id])\n  rev_Nx06DnItem_stopId Nx06DnItem[]   @relation(\"R_Nx06DnItem_stopId\")\n\n  @@map(\"nx06_dn_stop\")\n}\n\n/// =======================================================\n/// Nx07Attendance — DB table `nx07_attendance`\n/// =======================================================\nmodel Nx07Attendance {\n  /// [NX07]+[ATND]+[7碼流水號]，EX : NX07ATND0000001；啟用最低需求版本：PRO\n  id                String            @id @default(dbgenerated(\"gen_nx07_attendance_id()\")) @db.VarChar(15)\n  /// 租戶 ID（外鍵）。；啟用最低需求版本：PRO\n  tenantId          String            @map(\"tenant_id\") @db.VarChar(15)\n  /// 員工ID（FK nx01_user）。；啟用最低需求版本：PRO\n  userId            String            @map(\"user_id\") @db.VarChar(15)\n  /// 工作日期。；啟用最低需求版本：PRO\n  workDate          DateTime          @map(\"work_date\") @db.Date\n  /// 對應排班明細ID（FK nx07_schedule_item）。；啟用最低需求版本：PRO\n  scheduleItemId    String?           @map(\"schedule_item_id\") @db.VarChar(15)\n  /// 實際上班打卡時間。；啟用最低需求版本：PRO\n  clockInAt         DateTime?         @map(\"clock_in_at\")\n  /// 實際下班打卡時間。；啟用最低需求版本：PRO\n  clockOutAt        DateTime?         @map(\"clock_out_at\")\n  /// 上班打卡方式（I=IP驗證/M=手動/R=遠端）。；啟用最低需求版本：PRO\n  clockInMethod     String?           @map(\"clock_in_method\") @db.VarChar(1)\n  /// 下班打卡方式（I=IP驗證/M=手動/R=遠端）。；啟用最低需求版本：PRO\n  clockOutMethod    String?           @map(\"clock_out_method\") @db.VarChar(1)\n  /// 上班打卡IP位址。；啟用最低需求版本：PRO\n  clockInIp         String?           @map(\"clock_in_ip\") @db.VarChar(45)\n  /// 下班打卡IP位址。；啟用最低需求版本：PRO\n  clockOutIp        String?           @map(\"clock_out_ip\") @db.VarChar(45)\n  /// LINE Login 是否已驗證。；啟用最低需求版本：PRO\n  lineVerified      Boolean           @default(false) @map(\"line_verified\")\n  /// 基準上班時間（含主管審核補正後的時間）。；啟用最低需求版本：PRO\n  stdClockIn        DateTime?         @map(\"std_clock_in\")\n  /// 基準下班時間（含主管審核補正後的時間）。；啟用最低需求版本：PRO\n  stdClockOut       DateTime?         @map(\"std_clock_out\")\n  /// 遲到分鐘數（系統自動計算）。；啟用最低需求版本：PRO\n  lateMinutes       Int               @default(0) @map(\"late_minutes\")\n  /// 早退分鐘數（系統自動計算）。；啟用最低需求版本：PRO\n  earlyLeaveMinutes Int               @default(0) @map(\"early_leave_minutes\")\n  /// 實際工作時數（系統自動計算）。；啟用最低需求版本：PRO\n  workHours         Decimal           @default(0) @map(\"work_hours\") @db.Decimal(5, 2)\n  /// 加班時數（系統自動計算）。；啟用最低需求版本：PRO\n  overtimeHours     Decimal           @default(0) @map(\"overtime_hours\") @db.Decimal(5, 2)\n  /// 狀態（NORMAL/LATE/EARLY/ABSENT/SPECIAL 等；作廢以 voided_at 表示）。；啟用最低需求版本：PRO\n  status            String            @default(\"NORMAL\") @db.VarChar(30)\n  /// 主管審核人（遲到/早退/遠端打卡時填入）。；啟用最低需求版本：PRO\n  approvedBy        String?           @map(\"approved_by\") @db.VarChar(15)\n  /// 主管審核時間。；啟用最低需求版本：PRO\n  approvedAt        DateTime?         @map(\"approved_at\")\n  /// 審核說明（業務需求導致遲到/早退的原因）。；啟用最低需求版本：PRO\n  approveRemark     String?           @map(\"approve_remark\") @db.VarChar(200)\n  /// 作廢時間（DELETE 作廢）。；啟用最低需求版本：PRO\n  voidedAt          DateTime?         @map(\"voided_at\")\n  /// 建立時間。；啟用最低需求版本：PRO\n  createdAt         DateTime          @default(now()) @map(\"created_at\")\n  /// 建立人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：PRO\n  createdBy         String            @map(\"created_by\") @db.VarChar(15)\n  /// 更新時間。；啟用最低需求版本：PRO\n  updatedAt         DateTime          @updatedAt @map(\"updated_at\")\n  /// 更新人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：PRO\n  updatedBy         String            @map(\"updated_by\") @db.VarChar(15)\n  tenant            Nx99Tenant        @relation(\"R_Nx07Attendance_tenantId\", fields: [tenantId], references: [id])\n  user              Nx01User          @relation(\"R_Nx07Attendance_userId\", fields: [userId], references: [id])\n  scheduleItem      Nx07ScheduleItem? @relation(\"R_Nx07Attendance_scheduleItemId\", fields: [scheduleItemId], references: [id])\n\n  @@map(\"nx07_attendance\")\n}\n\n/// =======================================================\n/// Nx07IpWhitelist — DB table `nx07_ip_whitelist`\n/// =======================================================\nmodel Nx07IpWhitelist {\n  /// [NX07]+[IPWL]+[7碼流水號]，EX : NX07IPWL0000001；啟用最低需求版本：PRO\n  id          String         @id @default(dbgenerated(\"gen_nx07_ip_whitelist_id()\")) @db.VarChar(15)\n  /// 租戶 ID（外鍵）。；啟用最低需求版本：PRO\n  tenantId    String         @map(\"tenant_id\") @db.VarChar(15)\n  /// 對應倉庫ID（FK nx01_warehouse）。；啟用最低需求版本：PRO\n  warehouseId String?        @map(\"warehouse_id\") @db.VarChar(15)\n  /// IP 位址或 CIDR 範圍，例：192.168.1.0/24。；啟用最低需求版本：PRO\n  ipAddress   String         @map(\"ip_address\") @db.VarChar(45)\n  /// 名稱說明，例：Z01台北倉固定IP。；啟用最低需求版本：PRO\n  name        String         @db.VarChar(50)\n  /// 是否啟用。；啟用最低需求版本：PRO\n  isActive    Boolean        @default(true) @map(\"is_active\")\n  /// 建立時間。；啟用最低需求版本：PRO\n  createdAt   DateTime       @default(now()) @map(\"created_at\")\n  /// 建立人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：PRO\n  createdBy   String         @map(\"created_by\") @db.VarChar(15)\n  /// 更新時間。；啟用最低需求版本：PRO\n  updatedAt   DateTime       @updatedAt @map(\"updated_at\")\n  /// 更新人（必填；系統操作帶入使用者 ID；DB 匯入填系統管理員 ID）；啟用最低需求版本：PRO\n  updatedBy   String         @map(\"updated_by\") @db.VarChar(15)\n  tenant      Nx99Tenant     @relation(\"R_Nx07IpWhitelist_tenantId\", fields: [tenantId], references: [id])\n  warehouse   Nx01Warehouse? @relation(\"R_Nx07IpWhitelist_warehouseId\", fields: [warehouseId], references: [id])\n\n  @@map(\"nx07_ip_whitelist\")\n}\n\n/// =======================================================\n/// Nx07LeaveBalance — DB table `nx07_leave_balance`\n/// =======================================================\nmodel Nx07LeaveBalance {\n  /// [NX07]+[LVBL]+[7碼流水號]，EX : NX07LVBL0000001；啟用最低需求版本：PRO\n  id             String        @id @default(dbgenerated(\"gen_nx07_leave_balance_id()\")) @db.VarChar(15)\n  /// 租戶 ID（外鍵）。；啟用最低需求版本：PRO\n  tenantId       String        @map(\"tenant_id\") @db.VarChar(15)\n  /// 員工ID（FK nx01_user）。；啟用最低需求版本：PRO\n  userId         String        @map(\"user_id\") @db.VarChar(15)\n  /// 假別ID（FK nx07_leave_type）。；啟用最低需求版本：PRO\n  leaveTypeId    String        @map(\"leave_type_id\") @db.VarChar(15)\n  /// 年度，例：2026。；啟用最低需求版本：PRO\n  year           Int\n  /// 應有時數（依年資/勞基法計算）。；啟用最低需求版本：PRO\n  entitledHours  Decimal       @default(0) @map(\"entitled_hours\") @db.Decimal(6, 1)\n  /// 已使用時數。；啟用最低需求版本：PRO\n  usedHours      Decimal       @default(0) @map(\"used_hours\") @db.Decimal(6, 1)\n  /// 剩餘